-- Lesson: accumulation-of-change
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a15882956adb21', 'accumulation-of-change', 'Exploring accumulations of change', 'Interpret the area between a rate graph and the axis as the accumulated (net) change in a quantity, with units and signs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_586ce4997593bf', 'les_a15882956adb21', 1, 'Explain why area under a rate-of-change graph gives total change.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0e738184f9df4', 'les_a15882956adb21', 2, 'Compute accumulated change from rate graphs made of simple shapes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08a2be3fd89c4e', 'les_a15882956adb21', 3, 'Treat area below the axis as negative change.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_586ce4997593bf', 'les_a15882956adb21', 'learn', 1, 'definition', '{"term":"Rate × time = change","body":"If a rate is constant, change = rate × time: a rectangle''s area under the rate graph. For a varying rate, the (signed) area under the rate graph still gives the net change. Units: (rate units) × (input units)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0e738184f9df4', 'les_a15882956adb21', 'learn', 2, 'worked_example', '{"title":"Water flows into a tank at $r(t) = 10 - t$ gallons per minute for $0 \\le t \\le 10$.","steps":[{"latex":"\\text{area of the triangle} = \\tfrac{1}{2}(10)(10) = 50","explanation":""},{"latex":"\\text{the tank gains 50 gallons}","explanation":"gal/min × min = gal."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08a2be3fd89c4e', 'les_a15882956adb21', 'learn', 3, 'worked_example', '{"title":"A walker''s velocity is $3 - t$ m/s for $0 \\le t \\le 5$.","steps":[{"latex":"\\text{area above (0 to 3): } \\tfrac{1}{2}(3)(3) = 4.5","explanation":"Moving forward."},{"latex":"\\text{area below (3 to 5): } \\tfrac{1}{2}(2)(2) = 2","explanation":"Moving back."},{"latex":"\\text{net change in position } 4.5 - 2 = 2.5 \\text{ m}","explanation":"Total distance walked is 6.5 m."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e321a5a04df49', 'les_a15882956adb21', 'experiment', 4, 'activity', '{"activity":"accumulation","title":"Velocity builds displacement","params":{"fn":"velocity","x":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a994e1dff00c20', 'les_a15882956adb21', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Sweep $x$ past 3: the walker turns around, the area turns orange, and the lower graph starts going back down."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4fa01a8933f5c', 'les_a15882956adb21', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Utility meters accumulate a rate (kilowatts, liters per second) into a total (kilowatt-hours, liters): physically measuring the area under a rate curve."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_586ce4997593bf', 'les_a15882956adb21', 1, 'practice', 'numeric', 1, 'A car travels at a constant 25 m/s for 8 s. How far does it go, in meters?', '{"answer":200,"unit":"m"}', '[]', '$25 \times 8 = 200$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0e738184f9df4', 'les_a15882956adb21', 2, 'practice', 'numeric', 2, 'For the walker ($v = 3 - t$ on $[0, 5]$), what total distance is walked, in meters?', '{"answer":6.5,"tolerance":0.001,"unit":"m"}', '[]', '$4.5 + 2 = 6.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08a2be3fd89c4e', 'les_a15882956adb21', 3, 'practice', 'numeric', 2, 'A rate is 4 L/h for 2 hours, then −1 L/h for 3 hours. What is the net change, in liters?', '{"answer":5,"unit":"L"}', '[]', '$8 - 3 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e321a5a04df49', 'les_a15882956adb21', 4, 'review', 'multiple_choice', 3, 'A graph shows the rate at which people enter a stadium, in people per minute, against time in minutes. The area under it from 0 to 30 represents…', '{"choices":["The rate at minute 30","The number of people who entered in the first 30 minutes","The average rate","People per minute squared"],"answer":1}', '[]', '(people/min) × min = people.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a15882956adb21', (SELECT id FROM concepts WHERE slug = 'integrals'));

-- Lesson: antiderivatives-basic
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a7b7942c066a80', 'antiderivatives-basic', 'Finding antiderivatives and indefinite integrals: basic rules and notation', 'Find antiderivatives by reversing derivative rules, write indefinite integrals with +C, and use an initial condition to find a particular antiderivative.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eb3c4799b04054', 'les_a7b7942c066a80', 1, 'Use ∫xⁿ dx = xⁿ⁺¹/(n + 1) + C for n ≠ −1, and ∫(1/x) dx = ln|x| + C.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_97c9a53d065e28', 'les_a7b7942c066a80', 2, 'Antidifferentiate eˣ, sin x, cos x and sec² x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4a3a63441d7cf6', 'les_a7b7942c066a80', 3, 'Find the constant C from an initial condition.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb3c4799b04054', 'les_a7b7942c066a80', 'learn', 1, 'definition', '{"term":"Indefinite integral","body":"$\\int f(x)\\,dx = F(x) + C$ means $F''(x) = f(x)$. The $+C$ records that every vertical shift of $F$ also works."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97c9a53d065e28', 'les_a7b7942c066a80', 'learn', 2, 'definition', '{"term":"Basic rules","body":"$\\int x^n\\,dx = \\frac{x^{n+1}}{n + 1} + C$ ($n \\ne -1$); $\\int \\frac{1}{x}\\,dx = \\ln|x| + C$; $\\int e^x\\,dx = e^x + C$; $\\int \\cos x\\,dx = \\sin x + C$; $\\int \\sin x\\,dx = -\\cos x + C$; $\\int \\sec^2 x\\,dx = \\tan x + C$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a3a63441d7cf6', 'les_a7b7942c066a80', 'learn', 3, 'worked_example', '{"title":"$\\int \\left(6x^2 - \\frac{4}{x^3} + \\sqrt{x}\\right)dx$","steps":[{"latex":"= 2x^3 - 4\\cdot\\frac{x^{-2}}{-2} + \\frac{x^{3/2}}{3/2} + C","explanation":"Rewrite as powers first."},{"latex":"= 2x^3 + \\frac{2}{x^2} + \\tfrac{2}{3}x^{3/2} + C","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_76c286250bfe8f', 'les_a7b7942c066a80', 'learn', 4, 'worked_example', '{"title":"$f''(x) = 6x^2$ and $f(1) = 5$. Find $f$.","steps":[{"latex":"f(x) = 2x^3 + C","explanation":""},{"latex":"5 = 2 + C \\Rightarrow C = 3","explanation":""},{"latex":"f(x) = 2x^3 + 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_622db1354cf2e4', 'les_a7b7942c066a80', 'learn', 5, 'callout', '{"tone":"tip","title":"Check by differentiating","body":"Every antiderivative can be checked: differentiate your answer and you should get the integrand back."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b14c9a03cf2088', 'les_a7b7942c066a80', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Knowing a rocket''s acceleration and its starting velocity and position, two antiderivatives with initial conditions give its position at every time."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb3c4799b04054', 'les_a7b7942c066a80', 1, 'practice', 'numeric', 2, '$f''(x) = 3x^2 + 2$ and $f(0) = -1$. Find $f(2)$.', '{"answer":11}', '[]', '$f = x^3 + 2x - 1$; $f(2) = 8 + 4 - 1 = 11$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97c9a53d065e28', 'les_a7b7942c066a80', 2, 'practice', 'multiple_choice', 1, '$\int \cos x\,dx$ is…', '{"choices":["$-\\sin x + C$","$\\sin x + C$","$\\cos x + C$","$-\\cos x + C$"],"answer":1}', '[]', '$(\sin x)'' = \cos x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a3a63441d7cf6', 'les_a7b7942c066a80', 3, 'practice', 'multiple_choice', 2, '$\int \frac{3}{x}\,dx$ is…', '{"choices":["$3\\ln|x| + C$","$-\\frac{3}{x^2} + C$","$\\frac{3x^0}{0} + C$","$3x + C$"],"answer":0}', '[]', 'The power rule fails for $n = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_76c286250bfe8f', 'les_a7b7942c066a80', 4, 'review', 'numeric', 3, 'A ball is thrown up with velocity $v(t) = 20 - 9.8t$ m/s from height 2 m. Find its height at $t = 1$ s, in meters.', '{"answer":17.1,"tolerance":0.01,"unit":"m"}', '[]', '$h(t) = 2 + 20t - 4.9t^2$; $h(1) = 17.1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c82594985bd6b3', 'subj_math', 'antiderivatives', 'Antiderivatives', 'Functions whose derivative is a given function; written as indefinite integrals.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a7b7942c066a80', (SELECT id FROM concepts WHERE slug = 'antiderivatives'));

-- Lesson: candidates-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d8f1297e977f7f', 'candidates-test', 'Using the Candidates Test to determine absolute extrema', 'Find absolute maximum and minimum values on a closed interval by comparing f at critical points and endpoints.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_baa6444627dc43', 'les_d8f1297e977f7f', 1, 'List the candidates: critical points inside the interval and both endpoints.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_89e91c81f26646', 'les_d8f1297e977f7f', 2, 'Evaluate f at each candidate and compare.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96234b011213f7', 'les_d8f1297e977f7f', 3, 'Report the absolute extrema with their locations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_baa6444627dc43', 'les_d8f1297e977f7f', 'learn', 1, 'definition', '{"term":"Candidates Test (closed interval method)","body":"For $f$ continuous on $[a, b]$: 1. Find the critical points in $(a, b)$. 2. Evaluate $f$ at them and at $a$ and $b$. 3. The largest value is the absolute maximum; the smallest is the absolute minimum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89e91c81f26646', 'les_d8f1297e977f7f', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^3 - 12x + 1$ on $[-3, 5]$","steps":[{"latex":"\\text{critical points: } x = \\pm 2","explanation":"Both inside."},{"latex":"f(-3) = 10,\\ f(-2) = 17","explanation":"Endpoint and critical point on the left."},{"latex":"f(2) = -15,\\ f(5) = 66","explanation":"Critical point and endpoint on the right."},{"latex":"\\text{abs max } 66 \\text{ at } x = 5;\\ \\text{abs min } -15 \\text{ at } x = 2","explanation":"The relative max at −2 isn''t the absolute max."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96234b011213f7', 'les_d8f1297e977f7f', 'learn', 3, 'callout', '{"tone":"warning","title":"Only critical points inside the interval","body":"Ignore critical points outside $[a, b]$, and don''t forget the endpoints: they''re often where the absolute extremes occur."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e0e616612ad22', 'les_d8f1297e977f7f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"A business limited to producing between 0 and 500 units checks the profit at each critical point and at 0 and 500 to find the best plan."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_baa6444627dc43', 'les_d8f1297e977f7f', 1, 'practice', 'numeric', 1, 'Find the absolute maximum value of $f(x) = x^2 - 4x$ on $[0, 5]$.', '{"answer":5}', '[]', 'Candidates: $f(0) = 0$, $f(2) = -4$, $f(5) = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89e91c81f26646', 'les_d8f1297e977f7f', 2, 'practice', 'numeric', 1, 'Find the absolute minimum value of $f(x) = x^2 - 4x$ on $[0, 5]$.', '{"answer":-4}', '[]', 'At $x = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96234b011213f7', 'les_d8f1297e977f7f', 3, 'practice', 'numeric', 2, 'Find the absolute maximum value of $f(x) = \sin x + \cos x$ on $[0, \pi]$, to three decimal places.', '{"answer":1.414,"tolerance":0.001}', '["$f'' = \\cos x - \\sin x = 0$ at $\\frac{\\pi}{4}$."]', '$f(\frac{\pi}{4}) = \sqrt{2}$; $f(0) = 1$; $f(\pi) = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e0e616612ad22', 'les_d8f1297e977f7f', 4, 'review', 'multiple_choice', 3, 'On $[1, 4]$, $f(x) = x + \frac{4}{x}$. Where is the absolute minimum?', '{"choices":["x = 1","x = 2","x = 4","x = −2"],"answer":1}', '["$f''(x) = 1 - \\frac{4}{x^2}$."]', '$f(1) = 5$, $f(2) = 4$, $f(4) = 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eefbc6bdecd180', 'subj_math', 'extrema', 'Extrema', 'Maximum and minimum values of a function, locally or over its whole domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d8f1297e977f7f', (SELECT id FROM concepts WHERE slug = 'extrema'));

-- Lesson: concavity-inflection
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_da5202a04fc9b9', 'concavity-inflection', 'Determining concavity of functions over their domains', 'Use the sign of f″ to find intervals of concavity and points of inflection, and read concavity from graphs of f′.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_16692a2568b0dc', 'les_da5202a04fc9b9', 1, 'Find where f is concave up or down from the sign of f″.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f1376bf1cbb31', 'les_da5202a04fc9b9', 2, 'Locate points of inflection, where concavity changes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_068aaa96a796ca', 'les_da5202a04fc9b9', 3, 'Read concavity from where f′ is increasing or decreasing.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16692a2568b0dc', 'les_da5202a04fc9b9', 'learn', 1, 'definition', '{"term":"Concavity test","body":"If $f''''(x) > 0$ on an interval, $f$ is concave up there ($f''$ increasing); if $f''''(x) < 0$, concave down ($f''$ decreasing). A point of inflection is where $f$ is continuous and its concavity changes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f1376bf1cbb31', 'les_da5202a04fc9b9', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^4 - 4x^3$","steps":[{"latex":"f''''(x) = 12x^2 - 24x = 12x(x - 2)","explanation":""},{"latex":"f'''' > 0 \\text{ on } (-\\infty, 0) \\cup (2, \\infty)","explanation":"Concave up."},{"latex":"f'''' < 0 \\text{ on } (0, 2)","explanation":"Concave down."},{"latex":"\\text{inflection points at } x = 0 \\text{ and } x = 2","explanation":"f″ changes sign at both."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_068aaa96a796ca', 'les_da5202a04fc9b9', 'experiment', 3, 'activity', '{"activity":"derivative-graph","title":"Concavity from the slope of f′","params":{"fn":"quartic","a":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c8b3c6e48477ab', 'les_da5202a04fc9b9', 'learn', 4, 'callout', '{"tone":"warning","title":"f″ = 0 is not enough","body":"$f(x) = x^4$ has $f''''(0) = 0$, but it''s concave up on both sides: no inflection point. The sign must change."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bcf004d6e5c5d4', 'les_da5202a04fc9b9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"An epidemic''s case curve has an inflection point where new cases per day peak: concave up before (accelerating), concave down after (slowing)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16692a2568b0dc', 'les_da5202a04fc9b9', 1, 'practice', 'numeric', 1, 'Find the $x$-coordinate of the inflection point of $f(x) = x^3 - 6x^2$.', '{"answer":2}', '[]', '$f'''' = 6x - 12$ changes sign at 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f1376bf1cbb31', 'les_da5202a04fc9b9', 2, 'practice', 'multiple_choice', 2, 'On which interval is $f(x) = x^4 - 4x^3$ concave down?', '{"choices":["$(-\\infty, 0)$","$(0, 2)$","$(2, \\infty)$","nowhere"],"answer":1}', '[]', '$f'''' = 12x(x - 2) < 0$ there.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_068aaa96a796ca', 'les_da5202a04fc9b9', 3, 'practice', 'multiple_choice', 2, 'The graph of $f''$ is decreasing on $(3, 7)$. Then on $(3, 7)$, $f$ is…', '{"choices":["decreasing","concave down","negative","concave up"],"answer":1}', '[]', '$f''$ decreasing means $f'''' < 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c8b3c6e48477ab', 'les_da5202a04fc9b9', 4, 'review', 'multiple_choice', 3, 'Does $f(x) = x^{1/3}$ have an inflection point at $x = 0$?', '{"choices":["Yes: concavity changes there and f is continuous","No: f″(0) doesn''t exist","No: f′(0) doesn''t exist","No: it''s a cusp"],"answer":0}', '["Check the sign of $f'''' = -\\frac{2}{9}x^{-5/3}$ on each side."]', 'Concave up for $x < 0$, down for $x > 0$, and $f$ is continuous: an inflection point even though $f''''(0)$ is undefined.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_da5202a04fc9b9', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: connecting-f-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6d2ab1925c0e94', 'connecting-f-derivatives', 'Connecting a function, its first derivative and its second derivative', 'Summarize how the signs of f′ and f″ determine a graph''s shape, read all three from tables and graphs, and give AP-style justifications.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_47117db36d6a9f', 'les_6d2ab1925c0e94', 1, 'Match graphs of f, f′ and f″.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_084b566e7eba5a', 'les_6d2ab1925c0e94', 2, 'Combine sign information from f′ and f″ to describe a graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0ff69395b5b87e', 'les_6d2ab1925c0e94', 3, 'Justify claims using the correct derivative.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47117db36d6a9f', 'les_6d2ab1925c0e94', 'learn', 1, 'definition', '{"term":"The four shapes","body":"$f'' > 0, f'''' > 0$: increasing, concave up (rising faster). $f'' > 0, f'''' < 0$: increasing, concave down (rising slower). $f'' < 0, f'''' > 0$: decreasing, concave up (falling slower). $f'' < 0, f'''' < 0$: decreasing, concave down (falling faster)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_084b566e7eba5a', 'les_6d2ab1925c0e94', 'learn', 2, 'worked_example', '{"title":"Given a graph of $f''$ only","steps":[{"latex":"\\text{sign of } f'' \\to \\text{where } f \\text{ rises or falls}","explanation":""},{"latex":"\\text{slope of } f'' \\to \\text{sign of } f'''' \\to \\text{concavity of } f","explanation":""},{"latex":"\\text{zeros of } f'' \\text{ with sign change} \\to \\text{extrema of } f","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ff69395b5b87e', 'les_6d2ab1925c0e94', 'learn', 3, 'callout', '{"tone":"warning","title":"Use the right graph","body":"If you''re given the graph of $f''$, \"f is increasing because the graph is going up\" is wrong: you must point to $f'' > 0$ (the graph of $f''$ is above the axis)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2df80c54d1ee25', 'les_6d2ab1925c0e94', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Economic reports talk about growth (first derivative) slowing or speeding up (second derivative); a recession starts when growth turns negative."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47117db36d6a9f', 'les_6d2ab1925c0e94', 1, 'practice', 'multiple_choice', 1, '$f'' < 0$ and $f'''' > 0$ on an interval. The graph of $f$ is…', '{"choices":["rising faster","rising slower","falling, but less steeply","falling more steeply"],"answer":2}', '[]', 'Decreasing and concave up.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_084b566e7eba5a', 'les_6d2ab1925c0e94', 2, 'practice', 'multiple_choice', 2, 'A population''s growth rate is positive but decreasing. Which signs apply?', '{"choices":["P′ > 0, P″ > 0","P′ > 0, P″ < 0","P′ < 0, P″ > 0","P′ < 0, P″ < 0"],"answer":1}', '[]', 'Increasing population, slowing growth.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ff69395b5b87e', 'les_6d2ab1925c0e94', 3, 'practice', 'multiple_choice', 2, 'The graph of $f''''$ crosses from positive to negative at $x = 5$. At $x = 5$, $f$ has…', '{"choices":["a relative max","an inflection point","a relative min","a zero"],"answer":1}', '[]', 'Concavity changes.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2df80c54d1ee25', 'les_6d2ab1925c0e94', 4, 'review', 'multiple_choice', 3, 'Given only the graph of $f''$, which feature identifies a relative minimum of $f$?', '{"choices":["A minimum of the f′ graph","Where the f′ graph crosses the x-axis from below to above","Where the f′ graph crosses the x-axis from above to below","Where the f′ graph is lowest"],"answer":1}', '[]', '$f''$ changes from negative to positive.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6d2ab1925c0e94', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6d2ab1925c0e94', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: definite-integral-properties
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ba7589da869657', 'definite-integral-properties', 'Applying properties of definite integrals', 'Use linearity, additivity over adjacent intervals, reversed limits and geometric areas to evaluate and combine definite integrals.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4d720d3e1ce7b2', 'les_ba7589da869657', 1, 'Apply constant multiple and sum properties of integrals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e031dc5f0c25d1', 'les_ba7589da869657', 2, 'Split and combine integrals over adjacent intervals; reverse limits.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_88a99df0b0f0ca', 'les_ba7589da869657', 3, 'Evaluate integrals of piecewise or absolute value functions with geometry.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d720d3e1ce7b2', 'les_ba7589da869657', 'learn', 1, 'definition', '{"term":"Properties","body":"$\\int_a^b [kf(x) \\pm g(x)]\\,dx = k\\int_a^b f\\,dx \\pm \\int_a^b g\\,dx$; $\\int_a^c f = \\int_a^b f + \\int_b^c f$; $\\int_b^a f = -\\int_a^b f$; $\\int_a^a f = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e031dc5f0c25d1', 'les_ba7589da869657', 'learn', 2, 'worked_example', '{"title":"$\\int_0^5 f(x)\\,dx = 8$ and $\\int_0^2 f(x)\\,dx = 3$","steps":[{"latex":"\\int_2^5 f = 8 - 3 = 5","explanation":"Additivity."},{"latex":"\\int_5^2 f = -5","explanation":"Reversed limits."},{"latex":"\\int_0^5 [2f(x) + 1]\\,dx = 16 + 5 = 21","explanation":"$\\int_0^5 1\\,dx = 5$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_88a99df0b0f0ca', 'les_ba7589da869657', 'learn', 3, 'worked_example', '{"title":"$\\int_{-2}^{3} |x|\\,dx$","steps":[{"latex":"\\tfrac{1}{2}(2)(2) + \\tfrac{1}{2}(3)(3) = 2 + 4.5 = 6.5","explanation":"Two triangles."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a6667a65162d4', 'les_ba7589da869657', 'learn', 4, 'callout', '{"tone":"warning","title":"No product rule for integrals","body":"$\\int fg \\ne \\int f \\cdot \\int g$. Linearity covers sums and constant multiples only."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6619c92138b6c3', 'les_ba7589da869657', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Total energy used over a day is the sum of the integrals over each hour, which is additivity in action."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d720d3e1ce7b2', 'les_ba7589da869657', 1, 'practice', 'numeric', 1, 'If $\int_1^4 g(x)\,dx = 6$, find $\int_1^4 3g(x)\,dx$.', '{"answer":18}', '[]', '$3 \cdot 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e031dc5f0c25d1', 'les_ba7589da869657', 2, 'practice', 'numeric', 2, '$\int_0^{10} f = 12$ and $\int_6^{10} f = 4$. Find $\int_0^6 f$.', '{"answer":8}', '[]', '$12 - 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_88a99df0b0f0ca', 'les_ba7589da869657', 3, 'practice', 'numeric', 2, 'Find $\int_{-1}^{1} (x^3 + 2)\,dx$.', '{"answer":4}', '["$x^3$ is odd."]', '$\int x^3 = 0$ on a symmetric interval; $\int 2 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a6667a65162d4', 'les_ba7589da869657', 4, 'review', 'multiple_choice', 3, 'If $\int_2^7 f(x)\,dx = -3$, then $\int_7^2 [f(x) - 1]\,dx$ is…', '{"choices":["−8","2","8","−2"],"answer":2}', '[]', '$\int_7^2 f = 3$ and $\int_7^2 1\,dx = -5$; $3 - (-5) = 8$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ba7589da869657', (SELECT id FROM concepts WHERE slug = 'integrals'));

-- Lesson: exponential-models-de
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_feb66cccec0f8c', 'exponential-models-de', 'Exponential models with differential equations', 'Solve dy/dt = ky to get y = y₀eᵏᵗ, find k from doubling times or half-lives, and solve Newton''s law of cooling.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3517f4605cb392', 'les_feb66cccec0f8c', 1, 'Derive y = y₀eᵏᵗ from dy/dt = ky.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4eb3831cd04b4', 'les_feb66cccec0f8c', 2, 'Find k from a doubling time, half-life or two data points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_13b15acebb704a', 'les_feb66cccec0f8c', 3, 'Solve and apply Newton''s law of cooling.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3517f4605cb392', 'les_feb66cccec0f8c', 'learn', 1, 'definition', '{"term":"Exponential growth and decay","body":"$\\frac{dy}{dt} = ky$ has solution $y = y_0e^{kt}$: growth if $k > 0$, decay if $k < 0$. Doubling time $\\frac{\\ln 2}{k}$; half-life $\\frac{\\ln 2}{|k|}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4eb3831cd04b4', 'les_feb66cccec0f8c', 'learn', 2, 'worked_example', '{"title":"Bacteria double every 5 hours","steps":[{"latex":"e^{5k} = 2 \\Rightarrow k = \\frac{\\ln 2}{5} \\approx 0.1386 \\text{ per hour}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13b15acebb704a', 'les_feb66cccec0f8c', 'learn', 3, 'definition', '{"term":"Newton''s law of cooling","body":"$\\frac{dT}{dt} = -k(T - T_s)$ has solution $T = T_s + (T_0 - T_s)e^{-kt}$: the difference from the surroundings decays exponentially."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06ccaff7e80a58', 'les_feb66cccec0f8c', 'learn', 4, 'worked_example', '{"title":"Coffee at 90 °C in a 20 °C room is 60 °C after 10 min. Temperature at 20 min?","steps":[{"latex":"T - 20 = 70e^{-kt};\\ 40 = 70e^{-10k}","explanation":""},{"latex":"e^{-10k} = \\tfrac{4}{7}","explanation":""},{"latex":"T(20) = 20 + 70\\left(\\tfrac{4}{7}\\right)^2 \\approx 42.9 \\ \\text{°C}","explanation":"Each 10 minutes multiplies the gap by 4/7."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_afbb3cc1be7ac3', 'les_feb66cccec0f8c', 'experiment', 5, 'activity', '{"activity":"slope-field","title":"dy/dx = 0.5y","params":{"eq":"growth","x0":-2,"y0":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c917498e533b4d', 'les_feb66cccec0f8c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbon dating uses the half-life of carbon-14 (about 5,730 years); forensic investigators use Newton''s cooling to estimate time of death."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3517f4605cb392', 'les_feb66cccec0f8c', 1, 'practice', 'numeric', 2, 'Carbon-14 has a half-life of 5,730 years. What fraction remains after 2,000 years? Give four decimal places.', '{"answer":0.7851,"tolerance":0.0005}', '["$k = \\frac{\\ln 2}{5730}$."]', '$e^{-2000\ln 2/5730} = 2^{-2000/5730} \approx 0.7851$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4eb3831cd04b4', 'les_feb66cccec0f8c', 2, 'practice', 'numeric', 2, 'A population grows by $\frac{dP}{dt} = 0.04P$ from 500. Find $P(10)$, to the nearest whole number.', '{"answer":746,"tolerance":1}', '[]', '$500e^{0.4} \approx 745.9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13b15acebb704a', 'les_feb66cccec0f8c', 3, 'practice', 'numeric', 2, 'A quantity decays from 80 to 20 in 6 hours. What is its half-life, in hours?', '{"answer":3,"unit":"h"}', '[]', 'It halved twice in 6 hours.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06ccaff7e80a58', 'les_feb66cccec0f8c', 4, 'review', 'numeric', 3, 'For the coffee example, what temperature does the model predict after 30 minutes? One decimal place.', '{"answer":33.1,"tolerance":0.1,"unit":"°C"}', '[]', '$20 + 70\left(\frac{4}{7}\right)^3 = 20 + \frac{4480}{343} \approx 33.1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_feb66cccec0f8c', (SELECT id FROM concepts WHERE slug = 'differential-equations'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_feb66cccec0f8c', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_feb66cccec0f8c', (SELECT id FROM formulas WHERE slug = 'continuous-growth'), 1);

-- Lesson: extreme-value-critical-points
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7f61dc61ef58e7', 'extreme-value-critical-points', 'The Extreme Value Theorem, global versus local extrema, and critical points', 'Distinguish local from global extrema, state the Extreme Value Theorem, and find critical points where f′ is zero or undefined.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cef105c9a09e48', 'les_7f61dc61ef58e7', 1, 'Define local (relative) and global (absolute) extrema.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_93c1a0d2db1aee', 'les_7f61dc61ef58e7', 2, 'State when the EVT guarantees a maximum and minimum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6c4d6aa589768a', 'les_7f61dc61ef58e7', 3, 'Find critical points, including where f′ is undefined.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cef105c9a09e48', 'les_7f61dc61ef58e7', 'learn', 1, 'definition', '{"term":"Local and global extrema","body":"$f(c)$ is a local maximum if $f(c) \\ge f(x)$ for $x$ near $c$, and a global (absolute) maximum if $f(c) \\ge f(x)$ for all $x$ in the domain. Minimums are defined the same way."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93c1a0d2db1aee', 'les_7f61dc61ef58e7', 'learn', 2, 'definition', '{"term":"Extreme Value Theorem","body":"If $f$ is continuous on a closed interval $[a, b]$, then $f$ has both an absolute maximum and an absolute minimum on $[a, b]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c4d6aa589768a', 'les_7f61dc61ef58e7', 'learn', 3, 'definition', '{"term":"Critical points","body":"$c$ is a critical point of $f$ if $c$ is in the domain and $f''(c) = 0$ or $f''(c)$ is undefined. Local extrema inside an interval can only occur at critical points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2fba09e43eb8e1', 'les_7f61dc61ef58e7', 'learn', 4, 'worked_example', '{"title":"Critical points of $f(x) = x^3 - 12x$ and $g(x) = x^{2/3}$","steps":[{"latex":"f''(x) = 3x^2 - 12 = 0 \\Rightarrow x = \\pm 2","explanation":""},{"latex":"g''(x) = \\tfrac{2}{3}x^{-1/3},\\ \\text{undefined at } 0","explanation":"x = 0 is critical (a cusp minimum)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5235e27ea18cb', 'les_7f61dc61ef58e7', 'experiment', 5, 'activity', '{"activity":"derivative-graph","title":"Local extrema sit where f′ crosses zero","params":{"fn":"quartic","a":-1.4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cbefaa7a4ff8ed', 'les_7f61dc61ef58e7', 'learn', 6, 'callout', '{"tone":"warning","title":"Critical doesn''t mean extreme","body":"$f(x) = x^3$ has $f''(0) = 0$, but 0 isn''t a maximum or minimum. Critical points are only candidates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be1e4a16c2760b', 'les_7f61dc61ef58e7', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers look for critical points of stress in a beam: the maximum stress must occur at a critical point or at an end."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cef105c9a09e48', 'les_7f61dc61ef58e7', 1, 'practice', 'multiple_choice', 1, 'The critical points of $x^3 - 3x^2$ are…', '{"choices":["x = 0 only","x = 0 and x = 2","x = 3","x = 1 and x = 3"],"answer":1}', '[]', '$3x^2 - 6x = 3x(x - 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93c1a0d2db1aee', 'les_7f61dc61ef58e7', 2, 'practice', 'multiple_choice', 2, 'Which function is guaranteed an absolute max and min by the EVT?', '{"choices":["$\\frac{1}{x}$ on $[-1, 1]$","$x^2$ on $(0, 1)$","$\\sin x$ on $[0, 10]$","$\\tan x$ on $[0, \\pi]$"],"answer":2}', '[]', 'Continuous on a closed interval.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c4d6aa589768a', 'les_7f61dc61ef58e7', 3, 'practice', 'multiple_choice', 2, '$f(x) = |x - 2|$ has a critical point at…', '{"choices":["x = 0","x = 2","none","x = −2"],"answer":1}', '[]', '$f''(2)$ is undefined, and 2 is in the domain.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2fba09e43eb8e1', 'les_7f61dc61ef58e7', 4, 'review', 'multiple_choice', 3, 'On $(0, 1)$, $f(x) = x$ has…', '{"choices":["absolute max 1","absolute min 0","no absolute extrema","a critical point"],"answer":2}', '[]', 'The interval is open, so the endpoints aren''t included; the EVT doesn''t apply.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eefbc6bdecd180', 'subj_math', 'extrema', 'Extrema', 'Maximum and minimum values of a function, locally or over its whole domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7f61dc61ef58e7', (SELECT id FROM concepts WHERE slug = 'extrema'));

-- Lesson: first-derivative-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6c870a2d030a1f', 'first-derivative-test', 'Using the First Derivative Test to determine relative extrema', 'Classify critical points as relative maxima, minima or neither by how the sign of f′ changes across them.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_898c33e8ea1ead', 'les_6c870a2d030a1f', 1, 'Apply the First Derivative Test at each critical point.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_120a4b87962ddc', 'les_6c870a2d030a1f', 2, 'Recognize critical points where f′ doesn''t change sign.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d51776a2c1e065', 'les_6c870a2d030a1f', 3, 'Write a complete justification.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_898c33e8ea1ead', 'les_6c870a2d030a1f', 'learn', 1, 'definition', '{"term":"First Derivative Test","body":"At a critical point $c$ (with $f$ continuous at $c$): if $f''$ changes from positive to negative, $f(c)$ is a relative maximum; from negative to positive, a relative minimum; if $f''$ doesn''t change sign, there is no relative extremum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_120a4b87962ddc', 'les_6c870a2d030a1f', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^3 - 12x + 1$","steps":[{"latex":"f'' > 0 \\text{ on } (-\\infty, -2),\\ f'' < 0 \\text{ on } (-2, 2),\\ f'' > 0 \\text{ on } (2, \\infty)","explanation":""},{"latex":"\\text{relative max at } x = -2:\\ f(-2) = 17","explanation":"f′ changes from + to −."},{"latex":"\\text{relative min at } x = 2:\\ f(2) = -15","explanation":"f′ changes from − to +."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d51776a2c1e065', 'les_6c870a2d030a1f', 'learn', 3, 'worked_example', '{"title":"$f''(x) = (x - 1)^2(x + 3)$","steps":[{"latex":"\\text{sign change at } -3 \\ (- \\text{ to } +)","explanation":"Relative minimum at x = −3."},{"latex":"\\text{no sign change at } 1","explanation":"(x − 1)² ≥ 0: no extremum at x = 1."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0481ac93497226', 'les_6c870a2d030a1f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Reading a speed graph: when a runner''s velocity changes from positive to negative, they''ve reached their farthest point and turned around, a relative maximum of position."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_898c33e8ea1ead', 'les_6c870a2d030a1f', 1, 'practice', 'numeric', 1, '$f''$ changes from negative to positive at $x = 3$ and $f(3) = -4$. What is the relative minimum value?', '{"answer":-4}', '[]', 'A relative minimum at 3 with value $f(3) = -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_120a4b87962ddc', 'les_6c870a2d030a1f', 2, 'practice', 'multiple_choice', 2, '$f''(x) = x(x - 5)$. At $x = 5$, $f$ has…', '{"choices":["a relative max","a relative min","neither","an inflection point only"],"answer":1}', '[]', '$f''$ goes from − (between 0 and 5) to + (after 5).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d51776a2c1e065', 'les_6c870a2d030a1f', 3, 'practice', 'multiple_choice', 2, '$f''(x) = x^2(x - 2)$. At $x = 0$, $f$ has…', '{"choices":["a relative max","a relative min","neither","a cusp"],"answer":2}', '[]', '$f''$ is negative on both sides of 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0481ac93497226', 'les_6c870a2d030a1f', 4, 'review', 'multiple_choice', 3, 'Which justification for a relative maximum at $x = 4$ is complete?', '{"choices":["f′(4) = 0","f(4) is the largest value","f′ changes from positive to negative at x = 4","f″(4) = 0"],"answer":2}', '[]', 'The sign change is the justification.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eefbc6bdecd180', 'subj_math', 'extrema', 'Extrema', 'Maximum and minimum values of a function, locally or over its whole domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6c870a2d030a1f', (SELECT id FROM concepts WHERE slug = 'extrema'));

-- Lesson: ftc-accumulation-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_807164b8d0e0e9', 'ftc-accumulation-functions', 'The Fundamental Theorem of Calculus and accumulation functions', 'Define accumulation functions g(x) = ∫ₐˣ f(t) dt and use the first part of the Fundamental Theorem, g′(x) = f(x), including with the Chain Rule.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b19e4e92bde71', 'les_807164b8d0e0e9', 1, 'Define an accumulation function and evaluate it from geometry.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_073291346d8989', 'les_807164b8d0e0e9', 2, 'Apply d/dx ∫ₐˣ f(t) dt = f(x).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d361da4999c00a', 'les_807164b8d0e0e9', 3, 'Differentiate integrals with variable upper limits using the Chain Rule.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b19e4e92bde71', 'les_807164b8d0e0e9', 'learn', 1, 'definition', '{"term":"Accumulation function","body":"$g(x) = \\int_a^x f(t)\\,dt$ gives the signed area under $f$ from $a$ to $x$. The variable $t$ is a placeholder; $x$ is the input."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_073291346d8989', 'les_807164b8d0e0e9', 'learn', 2, 'definition', '{"term":"FTC, part 1","body":"If $f$ is continuous, then $g''(x) = \\frac{d}{dx}\\int_a^x f(t)\\,dt = f(x)$. Accumulated area grows at a rate equal to the current height of $f$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d361da4999c00a', 'les_807164b8d0e0e9', 'learn', 3, 'worked_example', '{"title":"Derivatives of accumulation functions","steps":[{"latex":"\\frac{d}{dx}\\int_2^x \\sqrt{1 + t^3}\\,dt = \\sqrt{1 + x^3}","explanation":""},{"latex":"\\frac{d}{dx}\\int_0^{x^2} \\cos t\\,dt = \\cos(x^2) \\cdot 2x","explanation":"Chain Rule with upper limit x²."},{"latex":"\\frac{d}{dx}\\int_x^5 e^{t^2}\\,dt = -e^{x^2}","explanation":"Flip the limits: a minus sign."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_952e887eb7e397', 'les_807164b8d0e0e9', 'experiment', 4, 'activity', '{"activity":"accumulation","title":"g′(x) = f(x)","params":{"fn":"sin","x":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2528db6b8e62fa', 'les_807164b8d0e0e9', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Compare the readout \"F′(x) = f(x)\" with the slope of the lower graph as you move $x$: where $f$ is largest, $F$ is steepest."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a89358c2f68d5', 'les_807164b8d0e0e9', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Total rainfall since midnight is an accumulation of the rainfall rate; the rate the total rises is the current rainfall rate, which is FTC part 1 in words."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b19e4e92bde71', 'les_807164b8d0e0e9', 1, 'practice', 'numeric', 1, 'If $g(x) = \int_1^x t^3\,dt$, find $g''(2)$.', '{"answer":8}', '[]', '$g''(x) = x^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_073291346d8989', 'les_807164b8d0e0e9', 2, 'practice', 'numeric', 2, 'If $h(x) = \int_0^{3x} \sqrt{t + 4}\,dt$, find $h''(0)$.', '{"answer":6}', '[]', '$h''(x) = \sqrt{3x + 4}\cdot 3$; at 0, $2 \cdot 3 = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d361da4999c00a', 'les_807164b8d0e0e9', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}\int_x^{1} \sin t\,dt$ is…', '{"choices":["$\\sin x$","$-\\sin x$","$\\cos x$","$\\sin 1 - \\sin x$"],"answer":1}', '[]', '$\int_x^1 = -\int_1^x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_952e887eb7e397', 'les_807164b8d0e0e9', 4, 'review', 'numeric', 3, 'If $g(x) = \int_0^x (t^2 - 4)\,dt$, at what $x > 0$ does $g$ have a critical point?', '{"answer":2}', '[]', '$g''(x) = x^2 - 4 = 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_807164b8d0e0e9', (SELECT id FROM concepts WHERE slug = 'integrals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_807164b8d0e0e9', (SELECT id FROM formulas WHERE slug = 'ftc'), 1);

-- Lesson: ftc-definite-integrals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cca798c7619b25', 'ftc-definite-integrals', 'The Fundamental Theorem of Calculus and definite integrals', 'Evaluate definite integrals with antiderivatives using FTC part 2, and interpret the result as net change.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46f65e23555a37', 'les_cca798c7619b25', 1, 'Evaluate ∫ₐᵇ f(x) dx = F(b) − F(a) for an antiderivative F.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa43e5a2770011', 'les_cca798c7619b25', 2, 'Use the net change theorem: ∫ₐᵇ F′(x) dx = F(b) − F(a).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d336abe890ccc2', 'les_cca798c7619b25', 3, 'Find a function value from a starting value and an integral of its rate.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46f65e23555a37', 'les_cca798c7619b25', 'learn', 1, 'definition', '{"term":"FTC, part 2","body":"If $f$ is continuous on $[a, b]$ and $F'' = f$, then $\\int_a^b f(x)\\,dx = F(b) - F(a)$, written $\\Big[F(x)\\Big]_a^b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa43e5a2770011', 'les_cca798c7619b25', 'learn', 2, 'worked_example', '{"title":"$\\int_1^3 x^2\\,dx$","steps":[{"latex":"\\left[\\tfrac{x^3}{3}\\right]_1^3 = 9 - \\tfrac{1}{3}","explanation":""},{"latex":"= \\tfrac{26}{3} \\approx 8.667","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d336abe890ccc2', 'les_cca798c7619b25', 'learn', 3, 'worked_example', '{"title":"$\\int_0^{\\pi} \\sin x\\,dx$","steps":[{"latex":"\\Big[-\\cos x\\Big]_0^{\\pi} = 1 - (-1) = 2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1cd992ac7b3050', 'les_cca798c7619b25', 'learn', 4, 'worked_example', '{"title":"A tank has 50 L at $t = 0$ and fills at $r(t) = 6t$ L/min. How much is in it at $t = 3$?","steps":[{"latex":"50 + \\int_0^3 6t\\,dt = 50 + \\Big[3t^2\\Big]_0^3","explanation":"Start value plus net change."},{"latex":"= 50 + 27 = 77 \\text{ L}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_078d0fc5800517', 'les_cca798c7619b25', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every physical \"total from a rate\" calculation, from distance traveled to drug absorbed, uses FTC part 2 to replace a limit of sums with two function values."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46f65e23555a37', 'les_cca798c7619b25', 1, 'practice', 'numeric', 1, 'Evaluate $\int_0^2 (3x^2 - 2x)\,dx$.', '{"answer":4}', '[]', '$[x^3 - x^2]_0^2 = 8 - 4 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa43e5a2770011', 'les_cca798c7619b25', 2, 'practice', 'numeric', 1, 'Evaluate $\int_1^e \frac{1}{x}\,dx$.', '{"answer":1}', '[]', '$\ln e - \ln 1 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d336abe890ccc2', 'les_cca798c7619b25', 3, 'practice', 'numeric', 2, 'Evaluate $\int_0^{1} e^x\,dx$ to three decimal places.', '{"answer":1.718,"tolerance":0.001}', '[]', '$e - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1cd992ac7b3050', 'les_cca798c7619b25', 4, 'practice', 'numeric', 2, '$f(2) = 5$ and $f''(x) = 4x$. Find $f(4)$.', '{"answer":29}', '[]', '$5 + \int_2^4 4x\,dx = 5 + [2x^2]_2^4 = 5 + 24 = 29$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_078d0fc5800517', 'les_cca798c7619b25', 5, 'review', 'multiple_choice', 3, '$\int_0^{2\pi} \sin x\,dx = 0$. What does this mean?', '{"choices":["The area between sin x and the axis is 0","The areas above and below the axis are equal, so the net signed area is 0","sin x = 0 on [0, 2π]","The integral doesn''t exist"],"answer":1}', '[]', 'Signed area cancels.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cca798c7619b25', (SELECT id FROM concepts WHERE slug = 'integrals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cca798c7619b25', (SELECT id FROM formulas WHERE slug = 'ftc'), 1);

-- Lesson: implicit-relations-behavior
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_61b4cc93571b40', 'implicit-relations-behavior', 'Exploring behaviors of implicit relations', 'Use implicit derivatives to find horizontal and vertical tangents, and to describe where an implicitly defined curve rises, falls and bends.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_18ec413163f217', 'les_61b4cc93571b40', 1, 'Find horizontal tangents (numerator of dy/dx zero) and vertical tangents (denominator zero).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c272bb46000f6', 'les_61b4cc93571b40', 2, 'Check that candidate points actually lie on the curve.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d0be5a61dd2c81', 'les_61b4cc93571b40', 3, 'Interpret the sign of dy/dx at points of the curve.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_18ec413163f217', 'les_61b4cc93571b40', 'learn', 1, 'definition', '{"term":"Tangents of implicit curves","body":"Write $\\frac{dy}{dx} = \\frac{N}{D}$. Horizontal tangents occur where $N = 0$ and $D \\ne 0$; vertical tangents where $D = 0$ and $N \\ne 0$. Substitute back into the original equation to find the actual points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c272bb46000f6', 'les_61b4cc93571b40', 'learn', 2, 'worked_example', '{"title":"$x^2 + xy + y^2 = 3$","steps":[{"latex":"2x + y + xy'' + 2yy'' = 0 \\Rightarrow y'' = -\\frac{2x + y}{x + 2y}","explanation":""},{"latex":"\\text{horizontal: } y = -2x \\Rightarrow 3x^2 = 3","explanation":""},{"latex":"(1, -2) \\text{ and } (-1, 2)","explanation":""},{"latex":"\\text{vertical: } x = -2y \\Rightarrow 3y^2 = 3 \\Rightarrow (-2, 1),\\ (2, -1)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d0be5a61dd2c81', 'les_61b4cc93571b40', 'learn', 3, 'callout', '{"tone":"warning","title":"Both zero?","body":"If the numerator and denominator are both 0 at a point, the test is inconclusive; examine the curve near that point."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cfd3513065586a', 'les_61b4cc93571b40', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Orbits and level curves of physical quantities are implicit; their highest and lowest points come from horizontal tangents."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_18ec413163f217', 'les_61b4cc93571b40', 1, 'practice', 'numeric', 1, 'For $x^2 + xy + y^2 = 3$, find $\frac{dy}{dx}$ at $(1, 1)$.', '{"answer":-1}', '[]', '$-\frac{2 + 1}{1 + 2} = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c272bb46000f6', 'les_61b4cc93571b40', 2, 'practice', 'multiple_choice', 2, 'For $x^2 + y^2 = 16$, horizontal tangents occur at…', '{"choices":["(±4, 0)","(0, ±4)","(4, 4)","none"],"answer":1}', '[]', '$y'' = -\frac{x}{y} = 0$ when $x = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d0be5a61dd2c81', 'les_61b4cc93571b40', 3, 'practice', 'numeric', 2, 'For $y^2 = x^3$, find $\frac{dy}{dx}$ at $(1, 1)$.', '{"answer":1.5,"tolerance":0.001}', '[]', '$2yy'' = 3x^2 \Rightarrow y'' = \frac{3}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cfd3513065586a', 'les_61b4cc93571b40', 4, 'review', 'multiple_choice', 3, 'For $y^2 = x^3$, what happens at $(0, 0)$?', '{"choices":["Horizontal tangent","Vertical tangent","dy/dx = 0/0: inconclusive (the curve has a cusp there)","dy/dx = 1"],"answer":2}', '[]', '$y'' = \frac{3x^2}{2y}$ gives $\frac{0}{0}$; the curve has a cusp.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_61b4cc93571b40', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: increasing-decreasing-intervals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ad71916acf079d', 'increasing-decreasing-intervals', 'Determining intervals on which a function is increasing or decreasing', 'Use the sign of f′ on a sign chart to find where f increases and decreases, and justify the answer in words.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_749644cf444bd1', 'les_ad71916acf079d', 1, 'Find critical points and build a sign chart for f′.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2f19a8e0e6b848', 'les_ad71916acf079d', 2, 'State intervals of increase and decrease.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_659ca909479d01', 'les_ad71916acf079d', 3, 'Justify the conclusion using the sign of f′.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_749644cf444bd1', 'les_ad71916acf079d', 'learn', 1, 'definition', '{"term":"The test","body":"If $f''(x) > 0$ on an interval, $f$ is increasing there; if $f''(x) < 0$, $f$ is decreasing. (This follows from the Mean Value Theorem.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2f19a8e0e6b848', 'les_ad71916acf079d', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^3 - 12x + 1$","steps":[{"latex":"f''(x) = 3(x - 2)(x + 2)","explanation":"Critical points −2 and 2."},{"latex":"f''(-3) = 15 > 0,\\ f''(0) = -12 < 0","explanation":"Test a point in each interval."},{"latex":"f''(3) = 15 > 0","explanation":""},{"latex":"\\text{increasing on } (-\\infty, -2) \\text{ and } (2, \\infty)","explanation":""},{"latex":"\\text{decreasing on } (-2, 2)","explanation":"Because f′ < 0 there."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_659ca909479d01', 'les_ad71916acf079d', 'experiment', 3, 'activity', '{"activity":"derivative-graph","title":"Read increase and decrease from f′","params":{"fn":"cubic","a":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44ad9d500fca25', 'les_ad71916acf079d', 'learn', 4, 'callout', '{"tone":"tip","title":"Justification","body":"A complete answer names the reason: \"$f$ is decreasing on $(-2, 2)$ because $f''(x) < 0$ on that interval.\" Pointing to the graph of $f''$ is fine if it''s given."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_365e8de620fd98', 'les_ad71916acf079d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"If a profit function''s derivative is positive, increasing production raises profit; where it turns negative, producing more starts to cost money."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_749644cf444bd1', 'les_ad71916acf079d', 1, 'practice', 'multiple_choice', 1, '$f''(x) = (x - 4)(x + 1)$. On which interval is $f$ decreasing?', '{"choices":["$(-\\infty, -1)$","$(-1, 4)$","$(4, \\infty)$","$(-\\infty, 4)$"],"answer":1}', '[]', '$f''(0) = -4 < 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2f19a8e0e6b848', 'les_ad71916acf079d', 2, 'practice', 'numeric', 2, '$f(x) = xe^{-x}$. $f$ is increasing for $x < k$. Find $k$.', '{"answer":1}', '[]', '$f'' = e^{-x}(1 - x) > 0$ when $x < 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_659ca909479d01', 'les_ad71916acf079d', 3, 'practice', 'multiple_choice', 2, '$f''(x) = x^2 + 1$. Then $f$ is…', '{"choices":["increasing everywhere","decreasing everywhere","increasing then decreasing","constant"],"answer":0}', '[]', '$f'' > 0$ for all $x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44ad9d500fca25', 'les_ad71916acf079d', 4, 'review', 'multiple_choice', 3, 'The graph of $f''$ is below the $x$-axis on $(1, 3)$. What does this tell you about $f$?', '{"choices":["f is negative on (1, 3)","f is decreasing on (1, 3)","f is concave down on (1, 3)","f has a minimum at 1"],"answer":1}', '[]', 'The sign of $f''$ gives the direction of $f$, not its sign.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eefbc6bdecd180', 'subj_math', 'extrema', 'Extrema', 'Maximum and minimum values of a function, locally or over its whole domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ad71916acf079d', (SELECT id FROM concepts WHERE slug = 'extrema'));

-- Lesson: integration-division-completing-square
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_69f8dbc71a3b3e', 'integration-division-completing-square', 'Integrating functions using long division and completing the square', 'Rewrite rational integrands with polynomial division, and complete the square to reach the arctangent form ∫ du/(u² + a²).', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_81659bc32fed5b', 'les_69f8dbc71a3b3e', 1, 'Use long division when the numerator''s degree is at least the denominator''s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3343895af99123', 'les_69f8dbc71a3b3e', 2, 'Complete the square in a quadratic denominator.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3863a610298350', 'les_69f8dbc71a3b3e', 3, 'Use ∫ du/(u² + a²) = (1/a) arctan(u/a) + C.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81659bc32fed5b', 'les_69f8dbc71a3b3e', 'learn', 1, 'worked_example', '{"title":"$\\int \\dfrac{x^2 + 1}{x + 1}\\,dx$","steps":[{"latex":"\\frac{x^2 + 1}{x + 1} = x - 1 + \\frac{2}{x + 1}","explanation":"Divide first."},{"latex":"= \\tfrac{x^2}{2} - x + 2\\ln|x + 1| + C","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3343895af99123', 'les_69f8dbc71a3b3e', 'learn', 2, 'definition', '{"term":"Arctangent form","body":"$\\int \\frac{du}{u^2 + a^2} = \\frac{1}{a}\\arctan\\frac{u}{a} + C$, from $(\\arctan x)'' = \\frac{1}{1 + x^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3863a610298350', 'les_69f8dbc71a3b3e', 'learn', 3, 'worked_example', '{"title":"$\\int \\dfrac{dx}{x^2 + 4x + 5}$","steps":[{"latex":"x^2 + 4x + 5 = (x + 2)^2 + 1","explanation":"Complete the square."},{"latex":"= \\arctan(x + 2) + C","explanation":"u = x + 2, a = 1."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0537bc4868a7d7', 'les_69f8dbc71a3b3e', 'learn', 4, 'callout', '{"tone":"tip","title":"Which tool?","body":"If the numerator''s degree ≥ the denominator''s, divide. If the denominator is an irreducible quadratic and the numerator is constant, complete the square for arctan. If the numerator is (a multiple of) the denominator''s derivative, substitute to get a logarithm."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22e144cf7a4953', 'les_69f8dbc71a3b3e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Integrals of $\\frac{1}{x^2 + a^2}$ appear in electric field calculations for a charged wire and in probability (the Cauchy distribution)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81659bc32fed5b', 'les_69f8dbc71a3b3e', 1, 'practice', 'numeric', 2, 'Evaluate $\int_{-2}^{-1} \dfrac{dx}{x^2 + 4x + 5}$ to three decimal places.', '{"answer":0.785,"tolerance":0.001}', '[]', '$\arctan(1) - \arctan(0) = \frac{\pi}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3343895af99123', 'les_69f8dbc71a3b3e', 2, 'practice', 'numeric', 2, 'Evaluate $\int_0^2 \dfrac{dx}{x^2 + 4}$ to three decimal places.', '{"answer":0.393,"tolerance":0.001}', '[]', '$\frac{1}{2}\arctan\frac{x}{2}\Big|_0^2 = \frac{1}{2}\cdot\frac{\pi}{4} = \frac{\pi}{8}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3863a610298350', 'les_69f8dbc71a3b3e', 3, 'practice', 'multiple_choice', 2, '$\dfrac{x^2}{x - 1}$ divides as…', '{"choices":["$x + 1 + \\frac{1}{x - 1}$","$x - 1 + \\frac{1}{x - 1}$","$x + \\frac{1}{x - 1}$","$x + 1$"],"answer":0}', '[]', '$(x - 1)(x + 1) = x^2 - 1$, remainder 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0537bc4868a7d7', 'les_69f8dbc71a3b3e', 4, 'review', 'multiple_choice', 3, 'Which method fits $\int \frac{2x + 4}{x^2 + 4x + 5}\,dx$?', '{"choices":["Completing the square for arctan","u = x² + 4x + 5, giving ln(x² + 4x + 5) + C","Long division","Power rule"],"answer":1}', '[]', 'The numerator is exactly the derivative of the denominator.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c82594985bd6b3', 'subj_math', 'antiderivatives', 'Antiderivatives', 'Functions whose derivative is a given function; written as indefinite integrals.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_69f8dbc71a3b3e', (SELECT id FROM concepts WHERE slug = 'antiderivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_69f8dbc71a3b3e', (SELECT id FROM formulas WHERE slug = 'inverse-derivatives'), 1);

-- Lesson: interpreting-accumulation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0671c45e615108', 'interpreting-accumulation', 'Interpreting the behavior of accumulation functions involving area', 'Analyze g(x) = ∫ₐˣ f(t) dt from the graph of f: values from areas, increase and decrease from the sign of f, extrema and concavity.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_78c0526ae57234', 'les_0671c45e615108', 1, 'Evaluate g at points from areas of geometric regions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5d7459ffb3cd07', 'les_0671c45e615108', 2, 'Find where g increases, decreases and has extrema from the sign of f.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b41b0066faf78', 'les_0671c45e615108', 3, 'Find concavity of g from whether f is increasing or decreasing.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_78c0526ae57234', 'les_0671c45e615108', 'learn', 1, 'definition', '{"term":"Reading g from f","body":"$g'' = f$ and $g'''' = f''$. So $g$ increases where $f > 0$, has a relative max where $f$ changes from positive to negative, and is concave up where $f$ is increasing."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d7459ffb3cd07', 'les_0671c45e615108', 'learn', 2, 'worked_example', '{"title":"$f(t) = 2 - t$ on $[0, 5]$ and $g(x) = \\int_0^x f(t)\\,dt$","steps":[{"latex":"g(2) = \\tfrac{1}{2}(2)(2) = 2","explanation":"Triangle above the axis."},{"latex":"g(4) = 2 - 2 = 0","explanation":"Equal triangle below."},{"latex":"g \\text{ max at } x = 2","explanation":"f changes from + to −."},{"latex":"g \\text{ concave down everywhere}","explanation":"f is decreasing (g″ = −1)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b41b0066faf78', 'les_0671c45e615108', 'experiment', 3, 'activity', '{"activity":"accumulation","title":"Where is g largest?","params":{"fn":"linear","x":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe077a9eeb96b8', 'les_0671c45e615108', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Find the $x$ where the lower graph peaks, then look at the upper graph: it''s exactly where $f$ crosses zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_512a294ec65a8b', 'les_0671c45e615108', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Water in a reservoir is the accumulation of inflow minus outflow; the reservoir is fullest exactly when net inflow turns from positive to negative."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_78c0526ae57234', 'les_0671c45e615108', 1, 'practice', 'numeric', 1, 'Using $f(t) = 2 - t$, find $g(5) = \int_0^5 f(t)\,dt$.', '{"answer":-2.5,"tolerance":0.001}', '[]', '$2 - \frac{1}{2}(3)(3) = 2 - 4.5 = -2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d7459ffb3cd07', 'les_0671c45e615108', 2, 'practice', 'multiple_choice', 2, '$g(x) = \int_0^x f(t)\,dt$, and $f$ is positive and decreasing on $(1, 3)$. On $(1, 3)$, $g$ is…', '{"choices":["increasing, concave up","increasing, concave down","decreasing, concave up","decreasing, concave down"],"answer":1}', '[]', '$g'' = f > 0$; $g'''' = f'' < 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b41b0066faf78', 'les_0671c45e615108', 3, 'practice', 'multiple_choice', 2, 'Where does $g(x) = \int_0^x \sin t\,dt$ have its relative maximum on $(0, 2\pi)$?', '{"choices":["$\\frac{\\pi}{2}$","$\\pi$","$\\frac{3\\pi}{2}$","$2\\pi$"],"answer":1}', '[]', '$\sin t$ changes from positive to negative at $\pi$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe077a9eeb96b8', 'les_0671c45e615108', 4, 'review', 'numeric', 3, 'Find $g(\pi)$ for $g(x) = \int_0^x \sin t\,dt$.', '{"answer":2}', '[]', '$1 - \cos\pi = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0671c45e615108', (SELECT id FROM concepts WHERE slug = 'integrals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0671c45e615108', (SELECT id FROM formulas WHERE slug = 'ftc'), 1);

-- Lesson: mean-value-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f772ba32aa88e3', 'mean-value-theorem', 'Using the Mean Value Theorem', 'State the Mean Value Theorem and Rolle''s Theorem, check their hypotheses, find the guaranteed value c, and justify conclusions about instantaneous rates.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eea923ee72aced', 'les_f772ba32aa88e3', 1, 'State the MVT and verify continuity and differentiability hypotheses.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_632599bb4c9ef4', 'les_f772ba32aa88e3', 2, 'Find values c where f′(c) equals the average rate of change.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba9308ed55872b', 'les_f772ba32aa88e3', 3, 'Use the MVT to justify that a rate was reached at some instant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eea923ee72aced', 'les_f772ba32aa88e3', 'learn', 1, 'definition', '{"term":"Mean Value Theorem","body":"If $f$ is continuous on $[a, b]$ and differentiable on $(a, b)$, then there is at least one $c$ in $(a, b)$ with $f''(c) = \\frac{f(b) - f(a)}{b - a}$. Rolle''s Theorem is the special case $f(a) = f(b)$, which guarantees $f''(c) = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_632599bb4c9ef4', 'les_f772ba32aa88e3', 'learn', 2, 'figure', '{"src":"/figures/mean-value-theorem.svg","alt":"The curve y = x cubed minus 3x from x = 0 to x = 2. A dashed secant line joins the endpoints. At one point c between them, a tangent line is drawn parallel to the secant.","caption":"The tangent at c has the same slope as the secant from a to b."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba9308ed55872b', 'les_f772ba32aa88e3', 'learn', 3, 'worked_example', '{"title":"$f(x) = x^3 - 3x$ on $[0, 2]$","steps":[{"latex":"\\frac{f(2) - f(0)}{2 - 0} = \\frac{2 - 0}{2} = 1","explanation":"Polynomial: continuous and differentiable."},{"latex":"f''(c) = 3c^2 - 3 = 1 \\Rightarrow c^2 = \\tfrac{4}{3}","explanation":""},{"latex":"c = \\tfrac{2}{\\sqrt{3}} \\approx 1.155","explanation":"Inside (0, 2); reject the negative root."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04d5fc48b98a8c', 'les_f772ba32aa88e3', 'learn', 4, 'worked_example', '{"title":"A car travels 120 miles in 2 hours.","steps":[{"latex":"\\text{average speed } 60 \\text{ mph}","explanation":""},{"latex":"\\text{position is differentiable, so by the MVT the speedometer read exactly 60 mph at some instant}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e00c7dd026e42', 'les_f772ba32aa88e3', 'learn', 5, 'callout', '{"tone":"warning","title":"Check the hypotheses","body":"$f(x) = |x|$ on $[-1, 1]$ has average rate 0, but $f''(c)$ is never 0: $f$ isn''t differentiable at 0, so the MVT doesn''t apply."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce5cb6ef302fb6', 'les_f772ba32aa88e3', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average-speed cameras on highways rely on the MVT: if your average speed between two cameras exceeded the limit, you were going faster than the limit at some instant."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eea923ee72aced', 'les_f772ba32aa88e3', 1, 'practice', 'numeric', 1, 'For $f(x) = x^2$ on $[1, 3]$, find the $c$ guaranteed by the MVT.', '{"answer":2}', '[]', 'Average rate $\frac{9 - 1}{2} = 4 = 2c$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_632599bb4c9ef4', 'les_f772ba32aa88e3', 2, 'practice', 'numeric', 2, 'For $f(x) = \sqrt{x}$ on $[0, 4]$, find $c$.', '{"answer":1}', '[]', 'Average rate $\frac{1}{2} = \frac{1}{2\sqrt{c}}$, so $c = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba9308ed55872b', 'les_f772ba32aa88e3', 3, 'practice', 'multiple_choice', 2, '$f$ is differentiable, $f(1) = 5$ and $f(4) = -1$. What must be true?', '{"choices":["f′(c) = −2 for some c in (1, 4)","f′(c) = 0 for some c in (1, 4)","f(c) = 0 for some c only","f′(x) = −2 everywhere"],"answer":0}', '[]', 'Average rate $\frac{-1 - 5}{3} = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04d5fc48b98a8c', 'les_f772ba32aa88e3', 4, 'review', 'multiple_choice', 3, 'Why doesn''t the MVT apply to $f(x) = \frac{1}{x}$ on $[-1, 1]$?', '{"choices":["f(−1) ≠ f(1)","f isn''t continuous on [−1, 1]","f is decreasing","It does apply"],"answer":1}', '[]', '$f$ is undefined at 0.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f772ba32aa88e3', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: modeling-differential-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f14abd7cd0c3b7', 'modeling-differential-equations', 'Modeling situations with differential equations', 'Translate verbal descriptions of rates, such as ''proportional to'' and ''Newton''s law of cooling'', into differential equations.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a88268117ef7a7', 'les_f14abd7cd0c3b7', 1, 'Write a differential equation from a description of a rate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9699a570719f7', 'les_f14abd7cd0c3b7', 2, 'Interpret the constant of proportionality and its sign.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3bef409ef1356a', 'les_f14abd7cd0c3b7', 3, 'Recognize growth, decay, cooling and logistic models.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a88268117ef7a7', 'les_f14abd7cd0c3b7', 'learn', 1, 'definition', '{"term":"Differential equation","body":"An equation involving a function and its derivative(s). \"The rate of change of $y$ is proportional to $y$\" becomes $\\frac{dy}{dt} = ky$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9699a570719f7', 'les_f14abd7cd0c3b7', 'learn', 2, 'worked_example', '{"title":"Translate each statement","steps":[{"latex":"\\frac{dP}{dt} = kP","explanation":"Population grows at a rate proportional to its size."},{"latex":"\\frac{dT}{dt} = -k(T - 20),\\ k > 0","explanation":"Newton''s cooling: rate proportional to the difference from room temperature (20 °C)."},{"latex":"\\frac{dP}{dt} = kP\\left(1 - \\frac{P}{M}\\right)","explanation":"Logistic: growth slows as P nears the capacity M."},{"latex":"\\frac{dV}{dt} = -k\\sqrt{h}","explanation":"Torricelli: a tank drains at a rate proportional to the square root of the depth."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3bef409ef1356a', 'les_f14abd7cd0c3b7', 'learn', 3, 'callout', '{"tone":"tip","title":"Read the units","body":"In $\\frac{dP}{dt} = 0.03P$, with $t$ in years, $k = 0.03$ per year: the population grows about 3% per year at any moment."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b1e8a32c8e1e2', 'les_f14abd7cd0c3b7', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Epidemiologists, engineers and economists model nearly everything that changes over time with differential equations, from disease spread to circuit currents."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a88268117ef7a7', 'les_f14abd7cd0c3b7', 1, 'practice', 'multiple_choice', 1, '"The rate of change of $A$ is proportional to the square of $A$" is…', '{"choices":["$\\frac{dA}{dt} = kA$","$\\frac{dA}{dt} = kA^2$","$A = kt^2$","$\\frac{dA}{dt} = k\\sqrt{A}$"],"answer":1}', '[]', 'Rate = k × A².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9699a570719f7', 'les_f14abd7cd0c3b7', 2, 'practice', 'multiple_choice', 2, 'In $\frac{dT}{dt} = -0.1(T - 25)$, a cup at 80 °C is…', '{"choices":["warming","cooling at 5.5 °C per minute","cooling at 8 °C per minute","at equilibrium"],"answer":1}', '[]', '$-0.1(55) = -5.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3bef409ef1356a', 'les_f14abd7cd0c3b7', 3, 'practice', 'multiple_choice', 2, 'A drug is eliminated at a rate proportional to the amount $A$ present. Which model?', '{"choices":["$\\frac{dA}{dt} = kA,\\ k > 0$","$\\frac{dA}{dt} = -kA,\\ k > 0$","$\\frac{dA}{dt} = k$","$A = kt$"],"answer":1}', '[]', 'Decreasing, so the rate is negative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b1e8a32c8e1e2', 'les_f14abd7cd0c3b7', 4, 'review', 'multiple_choice', 3, 'In the logistic model $\frac{dP}{dt} = 0.2P\left(1 - \frac{P}{500}\right)$, when is the population growing fastest?', '{"choices":["P = 0","P = 250","P = 500","P = 1000"],"answer":1}', '["Maximize $0.2P - 0.0004P^2$."]', 'Half the carrying capacity.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f14abd7cd0c3b7', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

-- Lesson: optimization-intro
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0fcddac436cf4a', 'optimization-intro', 'Introduction to optimization problems', 'Turn a word problem into a function of one variable on a sensible domain, then find its maximum or minimum with derivatives.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6119422b81060', 'les_0fcddac436cf4a', 1, 'Identify the quantity to optimize and the constraint.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7959059e6e67d4', 'les_0fcddac436cf4a', 2, 'Use the constraint to write the objective as a function of one variable with a domain.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5274cd938bdd09', 'les_0fcddac436cf4a', 3, 'Find and justify the optimal value.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6119422b81060', 'les_0fcddac436cf4a', 'learn', 1, 'definition', '{"term":"Setting up","body":"1. Name the quantity to maximize or minimize (the objective). 2. Write the constraint relating the variables. 3. Substitute so the objective uses one variable, and state its domain. 4. Find critical points and compare candidates (or use a derivative test)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7959059e6e67d4', 'les_0fcddac436cf4a', 'learn', 2, 'worked_example', '{"title":"400 m of fence encloses a rectangle against a river (no fence on the river side). Maximize the area.","steps":[{"latex":"\\text{objective } A = xy;\\ \\text{constraint } 2x + y = 400","explanation":"x: the two sides perpendicular to the river."},{"latex":"A(x) = x(400 - 2x),\\ 0 < x < 200","explanation":""},{"latex":"A''(x) = 400 - 4x = 0 \\Rightarrow x = 100","explanation":""},{"latex":"A(100) = 100 \\cdot 200 = 20{,}000 \\text{ m}^2","explanation":"A″ = −4 < 0 confirms a maximum."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5274cd938bdd09', 'les_0fcddac436cf4a', 'experiment', 3, 'activity', '{"activity":"optimization-box","title":"Find the best cut","params":{"length":12,"width":12,"x":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f68ec603065f47', 'les_0fcddac436cf4a', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"For a 12 × 12 sheet, find the cut with the largest volume by dragging $x$. Then check: $V''(x) = 12x^2 - 96x + 144 = 0$ gives $x = 2$, volume 128."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60187cec068502', 'les_0fcddac436cf4a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Packaging engineers choose dimensions that hold the most for the least material; farmers plan fields to enclose the most area with a given fence."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6119422b81060', 'les_0fcddac436cf4a', 1, 'practice', 'numeric', 1, 'Two positive numbers sum to 20. What is the largest possible product?', '{"answer":100}', '[]', '$P = x(20 - x)$; $P'' = 20 - 2x = 0$ at 10; $10 \cdot 10 = 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7959059e6e67d4', 'les_0fcddac436cf4a', 2, 'practice', 'numeric', 2, 'A rectangle has perimeter 60 cm. What is its maximum area, in cm²?', '{"answer":225,"unit":"cm²"}', '[]', '$A = x(30 - x)$, max at 15: a 15 × 15 square.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5274cd938bdd09', 'les_0fcddac436cf4a', 3, 'practice', 'numeric', 2, 'In the river problem with 600 m of fence, what is the maximum area in m²?', '{"answer":45000,"unit":"m²"}', '[]', '$A = x(600 - 2x)$, $x = 150$, $150 \cdot 300 = 45{,}000$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f68ec603065f47', 'les_0fcddac436cf4a', 4, 'review', 'numeric', 3, 'For a 12 × 12 sheet, what is the volume of the box when $x = 3$?', '{"answer":108}', '[]', '$3 \cdot 6 \cdot 6 = 108$, less than the maximum 128 at $x = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7021f21faa35ce', 'subj_math', 'optimization', 'Optimization', 'Finding the largest or smallest value of a quantity using derivatives.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0fcddac436cf4a', (SELECT id FROM concepts WHERE slug = 'optimization'));

-- Lesson: particular-solutions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bf3f70f80377e7', 'particular-solutions', 'Finding particular solutions using initial conditions and separation of variables', 'Solve initial value problems by separating, integrating, using the initial condition to find the constant, and choosing the correct branch and domain.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e138a3cce93931', 'les_bf3f70f80377e7', 1, 'Use the initial condition to find C right after integrating.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc7a0d689da40a', 'les_bf3f70f80377e7', 2, 'Choose the sign of a square root that matches the initial condition.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_94aca1f9177b19', 'les_bf3f70f80377e7', 3, 'State the domain on which the solution is valid.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e138a3cce93931', 'les_bf3f70f80377e7', 'learn', 1, 'definition', '{"term":"Initial value problem","body":"A differential equation plus a condition $y(x_0) = y_0$. Find $C$ as soon as you''ve integrated; it''s usually easiest before solving for $y$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc7a0d689da40a', 'les_bf3f70f80377e7', 'learn', 2, 'worked_example', '{"title":"$\\frac{dy}{dx} = xy$, $y(0) = 3$","steps":[{"latex":"\\ln|y| = \\tfrac{x^2}{2} + C","explanation":""},{"latex":"\\ln 3 = 0 + C","explanation":"Use the initial condition."},{"latex":"y = 3e^{x^2/2}","explanation":"So $y(2) = 3e^2 \\approx 22.17$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_94aca1f9177b19', 'les_bf3f70f80377e7', 'learn', 3, 'worked_example', '{"title":"$\\frac{dy}{dx} = \\frac{2x}{y}$, $y(0) = -2$","steps":[{"latex":"\\tfrac{y^2}{2} = x^2 + C \\Rightarrow C = 2","explanation":""},{"latex":"y^2 = 2x^2 + 4","explanation":""},{"latex":"y = -\\sqrt{2x^2 + 4}","explanation":"Negative root, to pass through (0, −2)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8de864932af773', 'les_bf3f70f80377e7', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every real prediction (how much medicine remains after 6 hours, how hot the coffee is after 20 minutes) needs a particular solution, fixed by a measured starting value."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e138a3cce93931', 'les_bf3f70f80377e7', 1, 'practice', 'numeric', 2, 'Solve $\frac{dy}{dx} = 2y$, $y(0) = 5$, and find $y(1)$ to two decimal places.', '{"answer":36.95,"tolerance":0.01}', '[]', '$y = 5e^{2x}$; $5e^2 \approx 36.95$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc7a0d689da40a', 'les_bf3f70f80377e7', 2, 'practice', 'numeric', 2, 'Solve $\frac{dy}{dx} = \frac{x}{y}$, $y(0) = 3$. Find $y(4)$.', '{"answer":5}', '["$y^2 = x^2 + 9$."]', 'Positive root: $\sqrt{25} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_94aca1f9177b19', 'les_bf3f70f80377e7', 3, 'practice', 'multiple_choice', 2, 'For $\frac{dy}{dx} = \frac{2x}{y}$ with $y(0) = -2$, what is $y(1)$?', '{"choices":["$\\sqrt{6}$","$-\\sqrt{6}$","−2","$\\pm\\sqrt{6}$"],"answer":1}', '[]', '$y = -\sqrt{2x^2 + 4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8de864932af773', 'les_bf3f70f80377e7', 4, 'review', 'numeric', 3, 'Solve $\frac{dy}{dx} = y^2$, $y(0) = 1$, and find $y(0.5)$.', '{"answer":2}', '["$-\\frac{1}{y} = x + C$."]', '$C = -1$, so $y = \frac{1}{1 - x}$, and $y(0.5) = 2$. The solution blows up at $x = 1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bf3f70f80377e7', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

-- Lesson: reasoning-slope-fields
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f47978aa62b92e', 'reasoning-slope-fields', 'Reasoning using slope fields', 'Match slope fields to differential equations, identify equilibrium solutions, and predict long-run behavior of solutions without solving.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1bce6c143dd1d', 'les_f47978aa62b92e', 1, 'Match a slope field to its equation using where slopes are zero, positive or negative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_181f6d899bb20a', 'les_f47978aa62b92e', 2, 'Identify equilibrium solutions and whether nearby solutions approach them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_54abc860c6ac40', 'les_f47978aa62b92e', 3, 'Predict long-term behavior from the field.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1bce6c143dd1d', 'les_f47978aa62b92e', 'learn', 1, 'definition', '{"term":"Clues for matching","body":"If slopes depend only on $x$, segments in each column are parallel. If only on $y$, segments in each row are parallel. Find where the slope is 0 and where it changes sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_181f6d899bb20a', 'les_f47978aa62b92e', 'learn', 2, 'worked_example', '{"title":"The logistic field $\\frac{dy}{dx} = 0.8y\\left(1 - \\frac{y}{4}\\right)$","steps":[{"latex":"\\text{equilibria: } y = 0,\\ y = 4","explanation":""},{"latex":"0 < y < 4:\\ \\text{slope} > 0","explanation":"Solutions rise toward 4."},{"latex":"y > 4:\\ \\text{slope} < 0","explanation":"Solutions fall toward 4. So y = 4 is stable."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54abc860c6ac40', 'les_f47978aa62b92e', 'experiment', 3, 'activity', '{"activity":"slope-field","title":"Logistic growth","params":{"eq":"logistic","x0":-4,"y0":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd29905fc36a38', 'les_f47978aa62b92e', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Start below 4 and above 4: both curves level off at $y = 4$. Start at a small negative $y$: the curve moves away from 0, so $y = 0$ is unstable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_317c9ab71fb25f', 'les_f47978aa62b92e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Fisheries managers use logistic models: a stable equilibrium at carrying capacity, and a fastest regrowth rate at half that level."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1bce6c143dd1d', 'les_f47978aa62b92e', 1, 'practice', 'multiple_choice', 1, 'In a slope field, all segments in each horizontal row are parallel. The equation is most likely…', '{"choices":["$\\frac{dy}{dx} = x^2$","$\\frac{dy}{dx} = y - 1$","$\\frac{dy}{dx} = x + y$","$\\frac{dy}{dx} = xy$"],"answer":1}', '[]', 'The slope depends only on $y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_181f6d899bb20a', 'les_f47978aa62b92e', 2, 'practice', 'multiple_choice', 2, 'For $\frac{dy}{dx} = 2 - y$, a solution starting at $y(0) = 5$…', '{"choices":["grows without bound","decreases toward 2","stays at 5","decreases toward 0"],"answer":1}', '[]', 'Slope negative above 2; equilibrium at 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_54abc860c6ac40', 'les_f47978aa62b92e', 3, 'practice', 'multiple_choice', 2, 'For $\frac{dy}{dx} = y^2 - 1$, which equilibrium is stable?', '{"choices":["y = 1","y = −1","both","neither"],"answer":1}', '["Check the sign of $y^2 - 1$ near each."]', 'Near −1, solutions move toward it (slope positive below, negative above).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd29905fc36a38', 'les_f47978aa62b92e', 4, 'review', 'multiple_choice', 3, 'Slopes are 0 along the line $y = x$, positive below it, negative above it. Which equation fits?', '{"choices":["$\\frac{dy}{dx} = x - y$","$\\frac{dy}{dx} = y - x$","$\\frac{dy}{dx} = xy$","$\\frac{dy}{dx} = x + y$"],"answer":0}', '[]', 'Below $y = x$, $x - y > 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f47978aa62b92e', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

-- Lesson: riemann-sums-notation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_92c948e312acc9', 'riemann-sums-notation', 'Riemann sums, summation notation and definite integral notation', 'Write Riemann sums in sigma notation, define the definite integral as their limit, and translate between limits of sums and integrals.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3cfd806a58ddc4', 'les_92c948e312acc9', 1, 'Write a right Riemann sum with sigma notation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b4112677556821', 'les_92c948e312acc9', 2, 'Define the definite integral as the limit of Riemann sums.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a39a333246f8c6', 'les_92c948e312acc9', 3, 'Convert a limit of a sum into a definite integral, and back.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3cfd806a58ddc4', 'les_92c948e312acc9', 'learn', 1, 'definition', '{"term":"Right Riemann sum","body":"With $n$ equal subintervals of $[a, b]$, $\\Delta x = \\frac{b - a}{n}$ and $x_i = a + i\\Delta x$, the right sum is $\\sum_{i=1}^{n} f(x_i)\\Delta x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4112677556821', 'les_92c948e312acc9', 'learn', 2, 'definition', '{"term":"Definite integral","body":"$\\int_a^b f(x)\\,dx = \\lim_{n \\to \\infty} \\sum_{i=1}^{n} f(x_i)\\Delta x$, when the limit exists. $f$ is the integrand; $a$ and $b$ are the limits of integration."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a39a333246f8c6', 'les_92c948e312acc9', 'learn', 3, 'worked_example', '{"title":"Write $\\lim_{n \\to \\infty} \\sum_{i=1}^{n} \\left(1 + \\frac{2i}{n}\\right)^2 \\frac{2}{n}$ as an integral","steps":[{"latex":"\\Delta x = \\tfrac{2}{n},\\ x_i = 1 + \\tfrac{2i}{n}","explanation":"So $a = 1$ and $b - a = 2$."},{"latex":"\\int_1^3 x^2\\,dx","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9edffa19a4ad2a', 'les_92c948e312acc9', 'learn', 4, 'worked_example', '{"title":"$R_4$ for $f(x) = x^2$ on $[0, 2]$","steps":[{"latex":"\\Delta x = 0.5;\\ x_i = 0.5, 1, 1.5, 2","explanation":""},{"latex":"0.5(0.25 + 1 + 2.25 + 4) = 3.75","explanation":"The exact value $\\int_0^2 x^2\\,dx = \\frac{8}{3} \\approx 2.67$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a48bf90e39cc9', 'les_92c948e312acc9', 'experiment', 5, 'activity', '{"activity":"riemann-sum","title":"From sums to the integral","params":{"fn":"x^2"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_809c5625f35235', 'les_92c948e312acc9', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Computers approximate integrals with sums like these (often the trapezoid rule) whenever no formula for an antiderivative exists."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3cfd806a58ddc4', 'les_92c948e312acc9', 1, 'practice', 'numeric', 1, 'Find $L_4$ (left sum) for $f(x) = x^2$ on $[0, 2]$.', '{"answer":1.75,"tolerance":0.001}', '["Left endpoints 0, 0.5, 1, 1.5."]', '$0.5(0 + 0.25 + 1 + 2.25) = 1.75$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b4112677556821', 'les_92c948e312acc9', 2, 'practice', 'multiple_choice', 2, '$\lim_{n \to \infty} \sum_{i=1}^{n} \sqrt{\frac{3i}{n}}\cdot\frac{3}{n}$ equals…', '{"choices":["$\\int_0^1 \\sqrt{x}\\,dx$","$\\int_0^3 \\sqrt{x}\\,dx$","$\\int_0^3 \\sqrt{3x}\\,dx$","$\\int_1^4 \\sqrt{x}\\,dx$"],"answer":1}', '[]', '$\Delta x = \frac{3}{n}$, $x_i = \frac{3i}{n}$, starting at 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a39a333246f8c6', 'les_92c948e312acc9', 3, 'practice', 'multiple_choice', 2, 'For an increasing function, a right Riemann sum is…', '{"choices":["an underestimate","an overestimate","exact","always zero"],"answer":1}', '[]', 'Right endpoints are the highest points of each strip.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9edffa19a4ad2a', 'les_92c948e312acc9', 4, 'review', 'numeric', 3, 'Evaluate $\sum_{i=1}^{4} (2i + 1)$.', '{"answer":24}', '[]', '$3 + 5 + 7 + 9 = 24$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d0e6d2a9b8ce95', 'subj_math', 'integrals', 'Definite integrals', 'The accumulated (signed) change of a quantity over an interval: area under a rate curve.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_92c948e312acc9', (SELECT id FROM concepts WHERE slug = 'integrals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_92c948e312acc9', (SELECT id FROM formulas WHERE slug = 'riemann-sum'), 1);

-- Lesson: second-derivative-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_70a98237d90106', 'second-derivative-test', 'Using the Second Derivative Test to determine extrema', 'Classify critical points where f′(c) = 0 using the sign of f″(c), and know when the test is inconclusive.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_037ca94b53fc4e', 'les_70a98237d90106', 1, 'Apply the Second Derivative Test at critical points with f′(c) = 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8a816a8ff9fac8', 'les_70a98237d90106', 2, 'Recognize when the test fails (f″(c) = 0).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_def918ba9f4a23', 'les_70a98237d90106', 3, 'Choose between the first and second derivative tests.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_037ca94b53fc4e', 'les_70a98237d90106', 'learn', 1, 'definition', '{"term":"Second Derivative Test","body":"If $f''(c) = 0$ and $f''''(c) > 0$, then $f(c)$ is a relative minimum (concave up, like a cup). If $f''(c) = 0$ and $f''''(c) < 0$, it is a relative maximum. If $f''''(c) = 0$, the test is inconclusive."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a816a8ff9fac8', 'les_70a98237d90106', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^3 - 12x + 1$","steps":[{"latex":"f''''(x) = 6x","explanation":""},{"latex":"f''''(-2) = -12 < 0 \\Rightarrow \\text{relative max}","explanation":""},{"latex":"f''''(2) = 12 > 0 \\Rightarrow \\text{relative min}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_def918ba9f4a23', 'les_70a98237d90106', 'learn', 3, 'worked_example', '{"title":"When it fails: $x^4$, $-x^4$ and $x^3$ at 0","steps":[{"latex":"f''(0) = 0,\\ f''''(0) = 0 \\text{ for all three}","explanation":""},{"latex":"\\text{min, max and neither}","explanation":"Use the First Derivative Test instead."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a00e4877821866', 'les_70a98237d90106', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"In physics, an equilibrium is stable if the potential energy has a minimum there: $U''(x) = 0$ and $U''''(x) > 0$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_037ca94b53fc4e', 'les_70a98237d90106', 1, 'practice', 'multiple_choice', 1, '$f''(3) = 0$ and $f''''(3) = -5$. At $x = 3$, $f$ has…', '{"choices":["a relative min","a relative max","an inflection point","no conclusion"],"answer":1}', '[]', 'Concave down at a critical point.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a816a8ff9fac8', 'les_70a98237d90106', 2, 'practice', 'multiple_choice', 2, '$f''(1) = 0$ and $f''''(1) = 0$. What can you conclude?', '{"choices":["Relative max","Relative min","Inflection point","Nothing from this test alone"],"answer":3}', '[]', 'Inconclusive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_def918ba9f4a23', 'les_70a98237d90106', 3, 'practice', 'numeric', 2, '$f(x) = x^2 e^{-x}$ has critical points 0 and 2. $f''''(x) = e^{-x}(x^2 - 4x + 2)$. Find $f''''(0)$.', '{"answer":2}', '[]', '$e^0(2) = 2 > 0$: relative min at 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a00e4877821866', 'les_70a98237d90106', 4, 'review', 'multiple_choice', 3, 'For the same function, $f''''(2) = e^{-2}(4 - 8 + 2)$. At $x = 2$, $f$ has…', '{"choices":["a relative min","a relative max","an inflection point","no extremum"],"answer":1}', '[]', '$f''''(2) = -2e^{-2} < 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_eefbc6bdecd180', 'subj_math', 'extrema', 'Extrema', 'Maximum and minimum values of a function, locally or over its whole domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_70a98237d90106', (SELECT id FROM concepts WHERE slug = 'extrema'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_70a98237d90106', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: selecting-antidifferentiation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ead06df9818d56', 'selecting-antidifferentiation', 'Selecting techniques for antidifferentiation', 'Choose a strategy for an integral: simplify algebraically, use a basic rule, substitute, divide or complete the square.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e3eb4b2155e28', 'les_ead06df9818d56', 1, 'Recognize when algebra (expanding, splitting fractions) makes an integral basic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_32ca41a06018fb', 'les_ead06df9818d56', 2, 'Spot a function and its derivative for substitution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eb81cbb36f1571', 'les_ead06df9818d56', 3, 'Pick division or completing the square for rational integrands.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e3eb4b2155e28', 'les_ead06df9818d56', 'learn', 1, 'definition', '{"term":"A checklist","body":"1. Is it a basic form, perhaps after rewriting (expand, split a fraction, use exponent rules)? 2. Is there an inner function with its derivative nearby (substitution)? 3. Is it a rational function? Divide if top-heavy; complete the square for arctan; look for ln."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32ca41a06018fb', 'les_ead06df9818d56', 'learn', 2, 'worked_example', '{"title":"Three integrals, three strategies","steps":[{"latex":"\\int \\frac{x^2 + 1}{x}\\,dx = \\int \\left(x + \\frac{1}{x}\\right)dx","explanation":"Split the fraction."},{"latex":"\\int \\sin x\\,e^{\\cos x}\\,dx = -e^{\\cos x} + C","explanation":"Substitute u = cos x."},{"latex":"\\int \\frac{dx}{9 + x^2} = \\tfrac{1}{3}\\arctan\\tfrac{x}{3} + C","explanation":"Arctangent form."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb81cbb36f1571', 'les_ead06df9818d56', 'learn', 3, 'callout', '{"tone":"tip","title":"Simplify first","body":"$\\int (x + 1)^2\\,dx$ works by substitution, but expanding to $x^2 + 2x + 1$ is just as quick, and both answers differ only by a constant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23b284d87a95ba', 'les_ead06df9818d56', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Computer algebra systems follow a similar checklist: they try simplifications and pattern matches before more expensive methods."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e3eb4b2155e28', 'les_ead06df9818d56', 1, 'practice', 'multiple_choice', 1, 'Best first step for $\int \frac{x^3 - x}{x}\,dx$?', '{"choices":["Substitution","Divide term by term to get x² − 1","Completing the square","Integration by parts"],"answer":1}', '[]', '$\int (x^2 - 1)\,dx$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32ca41a06018fb', 'les_ead06df9818d56', 2, 'practice', 'multiple_choice', 2, 'Best strategy for $\int x\cos(x^2)\,dx$?', '{"choices":["u = x²","u = cos x","Long division","Expand"],"answer":0}', '[]', '$du = 2x\,dx$ is present (up to a constant).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb81cbb36f1571', 'les_ead06df9818d56', 3, 'practice', 'multiple_choice', 2, '$\int \frac{x}{x^2 + 9}\,dx$ equals…', '{"choices":["$\\frac{1}{3}\\arctan\\frac{x}{3} + C$","$\\frac{1}{2}\\ln(x^2 + 9) + C$","$\\ln|x| + C$","$x - 9\\ln|x| + C$"],"answer":1}', '[]', '$u = x^2 + 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_23b284d87a95ba', 'les_ead06df9818d56', 4, 'review', 'multiple_choice', 3, '$\int \frac{1}{x^2 + 9}\,dx$ equals…', '{"choices":["$\\frac{1}{3}\\arctan\\frac{x}{3} + C$","$\\frac{1}{2}\\ln(x^2 + 9) + C$","$\\arctan x + C$","$\\frac{1}{9}\\arctan x + C$"],"answer":0}', '[]', 'Arctangent form with $a = 3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c82594985bd6b3', 'subj_math', 'antiderivatives', 'Antiderivatives', 'Functions whose derivative is a given function; written as indefinite integrals.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ead06df9818d56', (SELECT id FROM concepts WHERE slug = 'antiderivatives'));

-- Lesson: separation-of-variables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_db17774dea6bea', 'separation-of-variables', 'Finding general solutions using separation of variables', 'Solve separable differential equations by moving all y-terms to one side and x-terms to the other, integrating both sides, and solving for y.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7416657342731c', 'les_db17774dea6bea', 1, 'Recognize separable equations dy/dx = g(x)h(y).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3452d40e25a57d', 'les_db17774dea6bea', 2, 'Separate, integrate both sides, and include one constant.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a6c4371c907273', 'les_db17774dea6bea', 3, 'Solve for y when possible.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7416657342731c', 'les_db17774dea6bea', 'learn', 1, 'definition', '{"term":"Separation","body":"If $\\frac{dy}{dx} = g(x)h(y)$, rewrite as $\\frac{1}{h(y)}\\,dy = g(x)\\,dx$, integrate both sides, and solve for $y$. One constant $C$ is enough."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3452d40e25a57d', 'les_db17774dea6bea', 'learn', 2, 'worked_example', '{"title":"$\\frac{dy}{dx} = xy$","steps":[{"latex":"\\frac{dy}{y} = x\\,dx","explanation":""},{"latex":"\\ln|y| = \\tfrac{x^2}{2} + C","explanation":""},{"latex":"y = Ae^{x^2/2}","explanation":"Where $A = \\pm e^C$ (and $A = 0$ gives the solution $y = 0$)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6c4371c907273', 'les_db17774dea6bea', 'learn', 3, 'worked_example', '{"title":"$\\frac{dy}{dx} = \\frac{x}{y}$","steps":[{"latex":"y\\,dy = x\\,dx","explanation":""},{"latex":"\\tfrac{y^2}{2} = \\tfrac{x^2}{2} + C \\Rightarrow y^2 = x^2 + K","explanation":"A family of hyperbolas."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d0b2e0d38b570c', 'les_db17774dea6bea', 'learn', 4, 'callout', '{"tone":"warning","title":"Not every equation separates","body":"$\\frac{dy}{dx} = x + y$ can''t be written as $g(x)h(y)$; separation doesn''t apply."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ac492e71a053b', 'les_db17774dea6bea', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Radioactive decay, Newton''s cooling, and drug elimination are all separable, which is why they have tidy exponential solutions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7416657342731c', 'les_db17774dea6bea', 1, 'practice', 'multiple_choice', 1, 'Which equation is separable?', '{"choices":["$\\frac{dy}{dx} = x + y$","$\\frac{dy}{dx} = x^2 y^3$","$\\frac{dy}{dx} = \\sin(xy)$","$\\frac{dy}{dx} = x - y^2 + 1$"],"answer":1}', '[]', '$g(x) = x^2$, $h(y) = y^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3452d40e25a57d', 'les_db17774dea6bea', 2, 'practice', 'multiple_choice', 2, 'The general solution of $\frac{dy}{dx} = 3x^2 y$ is…', '{"choices":["$y = Ce^{x^3}$","$y = x^3 + C$","$y = Ce^{3x}$","$y = e^{x^3} + C$"],"answer":0}', '[]', '$\ln|y| = x^3 + C$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a6c4371c907273', 'les_db17774dea6bea', 3, 'practice', 'multiple_choice', 2, 'Separating $\frac{dy}{dx} = \frac{\cos x}{y^2}$ gives…', '{"choices":["$y^2\\,dy = \\cos x\\,dx$","$dy = y^2\\cos x\\,dx$","$\\frac{dy}{y^2} = \\cos x\\,dx$","$y\\,dy = \\cos x\\,dx$"],"answer":0}', '[]', 'Then $\frac{y^3}{3} = \sin x + C$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d0b2e0d38b570c', 'les_db17774dea6bea', 4, 'review', 'multiple_choice', 3, 'Why is only one constant needed after integrating both sides?', '{"choices":["Constants cancel","Two constants combine into one","The left side has no constant","It''s a convention only"],"answer":1}', '[]', '$C_1 - C_2$ is a single arbitrary constant.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_db17774dea6bea', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

-- Lesson: sketching-f-and-derivative
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_45acd6e60cd11c', 'sketching-f-and-derivative', 'Sketching graphs of functions and their derivatives', 'Sketch the graph of f′ from a graph of f and sketch a possible f from a graph of f′, using slopes, extrema and concavity.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42b64dfa30e5a3', 'les_45acd6e60cd11c', 1, 'Sketch f′ from f: zeros of f′ at horizontal tangents, sign from increase or decrease.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_57e67b739768bc', 'les_45acd6e60cd11c', 2, 'Sketch f from f′: extrema where f′ changes sign, inflection points at extrema of f′.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_512f95fefa459e', 'les_45acd6e60cd11c', 3, 'Recognize that f is determined by f′ only up to a vertical shift.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42b64dfa30e5a3', 'les_45acd6e60cd11c', 'learn', 1, 'definition', '{"term":"From f to f′","body":"Where $f$ has a horizontal tangent, $f''$ crosses or touches 0. Where $f$ rises, $f''$ is above the axis; where it falls, below. Where $f$ is steepest, $f''$ has its largest magnitude."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57e67b739768bc', 'les_45acd6e60cd11c', 'learn', 2, 'definition', '{"term":"From f′ to f","body":"Where $f''$ changes sign, $f$ has a relative extremum. Where $f''$ has a maximum or minimum, $f$ has an inflection point. Any vertical shift of $f$ has the same $f''$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_512f95fefa459e', 'les_45acd6e60cd11c', 'learn', 3, 'worked_example', '{"title":"$f''$ is a downward parabola with zeros at 0 and 4","steps":[{"latex":"f'' < 0 \\text{ for } x < 0,\\ f'' > 0 \\text{ on } (0, 4),\\ f'' < 0 \\text{ for } x > 4","explanation":""},{"latex":"f \\text{ has a relative min at } 0 \\text{ and a relative max at } 4","explanation":""},{"latex":"f'' \\text{ peaks at } x = 2 \\Rightarrow \\text{inflection point of } f","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_372f696eb93365', 'les_45acd6e60cd11c', 'experiment', 4, 'activity', '{"activity":"derivative-graph","title":"Match f to f′","params":{"fn":"sin","a":1.57}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e602376d8be62', 'les_45acd6e60cd11c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Before moving the slider, predict the shape of the lower graph from the upper one. Check yourself with each function."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c2f9ab27df479f', 'les_45acd6e60cd11c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"A velocity graph from a fitness tracker can be turned into a rough position graph, and vice versa, using exactly these ideas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42b64dfa30e5a3', 'les_45acd6e60cd11c', 1, 'practice', 'multiple_choice', 1, '$f$ has a relative maximum at $x = 2$ and is differentiable. On the graph of $f''$, at $x = 2$…', '{"choices":["f′ has a maximum","f′ crosses the axis from above to below","f′ crosses from below to above","f′ is undefined"],"answer":1}', '[]', '$f''$ changes from positive to negative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57e67b739768bc', 'les_45acd6e60cd11c', 2, 'practice', 'multiple_choice', 2, '$f''$ has a relative minimum at $x = -1$. Then $f$ has…', '{"choices":["a relative min at −1","an inflection point at −1","a relative max at −1","a zero at −1"],"answer":1}', '[]', '$f''''$ changes sign there.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_512f95fefa459e', 'les_45acd6e60cd11c', 3, 'practice', 'multiple_choice', 2, '$f(x)$ and $g(x) = f(x) + 7$ have derivatives that are…', '{"choices":["the same","differ by 7","differ by 7x","unrelated"],"answer":0}', '[]', 'The derivative of a constant is 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_372f696eb93365', 'les_45acd6e60cd11c', 4, 'review', 'multiple_choice', 3, '$f''$ is positive and decreasing on $(1, 3)$. Then on $(1, 3)$, $f$ is…', '{"choices":["increasing and concave up","increasing and concave down","decreasing and concave up","decreasing and concave down"],"answer":1}', '[]', '$f'' > 0$: increasing; $f''$ decreasing: concave down.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_45acd6e60cd11c', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: sketching-slope-fields
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_58676f373f72f0', 'sketching-slope-fields', 'Sketching slope fields', 'Draw slope fields by evaluating dy/dx at grid points, use isoclines to speed up sketching, and sketch solution curves through given points.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_801eb6cd60a8f8', 'les_58676f373f72f0', 1, 'Compute slopes at grid points and draw short segments.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d9283c2906733e', 'les_58676f373f72f0', 2, 'Use isoclines (curves of constant slope) to organize the sketch.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5260e031603625', 'les_58676f373f72f0', 3, 'Sketch a solution curve that follows the field.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_801eb6cd60a8f8', 'les_58676f373f72f0', 'learn', 1, 'definition', '{"term":"Slope field","body":"For $\\frac{dy}{dx} = f(x, y)$, draw at each grid point a short segment with slope $f(x, y)$. Solution curves are tangent to the segments everywhere."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9283c2906733e', 'les_58676f373f72f0', 'learn', 2, 'worked_example', '{"title":"$\\frac{dy}{dx} = x - y$","steps":[{"latex":"(1, 0): 1;\\ (0, 1): -1;\\ (2, 2): 0","explanation":"Slopes at a few points."},{"latex":"\\text{slope 0 along } y = x","explanation":"An isocline: all segments there are flat."},{"latex":"\\text{slope 1 along } y = x - 1","explanation":"And that line is itself a solution, since $y'' = 1 = x - (x - 1)$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5260e031603625', 'les_58676f373f72f0', 'experiment', 3, 'activity', '{"activity":"slope-field","title":"dy/dx = x − y","params":{"eq":"x-y","x0":0,"y0":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa551f5ec222c2', 'les_58676f373f72f0', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Start at $(0, -1)$: the solution is the straight line $y = x - 1$. Start anywhere else and the curve approaches that line as $x$ grows."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46d1a06d604ed9', 'les_58676f373f72f0', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Weather maps of wind direction and ocean current charts are slope fields; a drifting buoy traces a solution curve."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_801eb6cd60a8f8', 'les_58676f373f72f0', 1, 'practice', 'numeric', 1, 'For $\frac{dy}{dx} = x - y$, what slope is drawn at $(3, 1)$?', '{"answer":2}', '[]', '$3 - 1 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9283c2906733e', 'les_58676f373f72f0', 2, 'practice', 'numeric', 2, 'For $\frac{dy}{dx} = xy$, what slope is drawn at $(-1, 2)$?', '{"answer":-2}', '[]', '$(-1)(2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5260e031603625', 'les_58676f373f72f0', 3, 'practice', 'multiple_choice', 2, 'In the slope field of $\frac{dy}{dx} = x^2$, segments along any vertical line…', '{"choices":["are all parallel","are all horizontal","get steeper as y increases","are undefined"],"answer":0}', '[]', 'The slope depends only on $x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa551f5ec222c2', 'les_58676f373f72f0', 4, 'review', 'multiple_choice', 3, 'For $\frac{dy}{dx} = y(2 - y)$, which horizontal lines are solutions?', '{"choices":["y = 0 and y = 2","y = 1 only","x = 0 and x = 2","none"],"answer":0}', '[]', '$\frac{dy}{dx} = 0$ there for all $x$: equilibrium solutions.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_58676f373f72f0', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

-- Lesson: solving-optimization
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9ad1a5709ec4d6', 'solving-optimization', 'Solving optimization problems', 'Solve geometric and applied optimization problems such as minimum surface area, minimum distance and maximum volume, and justify that the answer is a global optimum.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_123ce7dd7acc9e', 'les_9ad1a5709ec4d6', 1, 'Solve multi-step optimization problems from geometry and applications.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_32bd9dc65f98a8', 'les_9ad1a5709ec4d6', 2, 'Simplify by optimizing the square of a distance.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6d03f761b0e7fb', 'les_9ad1a5709ec4d6', 3, 'Justify a global optimum with the Candidates Test or a single critical point argument.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_123ce7dd7acc9e', 'les_9ad1a5709ec4d6', 'learn', 1, 'worked_example', '{"title":"A can must hold 1000 cm³. Minimize the metal used (surface area).","steps":[{"latex":"\\pi r^2 h = 1000 \\Rightarrow h = \\frac{1000}{\\pi r^2}","explanation":"Constraint."},{"latex":"S(r) = 2\\pi r^2 + 2\\pi r h = 2\\pi r^2 + \\frac{2000}{r}","explanation":""},{"latex":"S''(r) = 4\\pi r - \\frac{2000}{r^2} = 0","explanation":""},{"latex":"r^3 = \\frac{500}{\\pi} \\Rightarrow r \\approx 5.42 \\text{ cm}","explanation":"Then h = 2r ≈ 10.84 cm."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32bd9dc65f98a8', 'les_9ad1a5709ec4d6', 'learn', 2, 'worked_example', '{"title":"Closest point on $y = \\sqrt{x}$ to $(4, 0)$","steps":[{"latex":"D^2 = (x - 4)^2 + x","explanation":"Minimizing D² minimizes D."},{"latex":"\\frac{d}{dx}D^2 = 2(x - 4) + 1 = 0 \\Rightarrow x = 3.5","explanation":""},{"latex":"\\text{point } (3.5, \\sqrt{3.5}) \\approx (3.5, 1.87)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d03f761b0e7fb', 'les_9ad1a5709ec4d6', 'learn', 3, 'definition', '{"term":"Justifying a global optimum","body":"On a closed interval, use the Candidates Test. On an open interval, if there is only one critical point and it''s a relative minimum (or maximum), it''s the absolute one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15deaba6c5af8a', 'les_9ad1a5709ec4d6', 'experiment', 4, 'activity', '{"activity":"optimization-box","title":"A rectangular sheet","params":{"length":16,"width":10,"x":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68e62dadaafa8b', 'les_9ad1a5709ec4d6', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"For a 16 × 10 sheet the best cut is exactly 2, giving volume $2 \\cdot 12 \\cdot 6 = 144$. Change the sheet and watch the best cut move."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50b78934eeb7f4', 'les_9ad1a5709ec4d6', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Real cans are taller than the \"optimal\" 2r because the top and bottom use thicker metal, a reminder to check a model''s assumptions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_123ce7dd7acc9e', 'les_9ad1a5709ec4d6', 1, 'practice', 'numeric', 2, 'For the can problem, what is the optimal height-to-radius ratio $h/r$?', '{"answer":2}', '[]', 'At the optimum, $h = \frac{1000}{\pi r^2}$ and $\pi r^3 = 500$ give $h = 2r$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32bd9dc65f98a8', 'les_9ad1a5709ec4d6', 2, 'practice', 'numeric', 2, 'Find the $x$-coordinate of the point on $y = x^2$ closest to $(0, 2)$, with $x > 0$. Round to three decimal places.', '{"answer":1.225,"tolerance":0.002}', '["Minimize $x^2 + (x^2 - 2)^2$."]', 'Derivative $2x + 4x(x^2 - 2) = 2x(2x^2 - 3) = 0 \Rightarrow x = \sqrt{1.5} \approx 1.225$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d03f761b0e7fb', 'les_9ad1a5709ec4d6', 3, 'practice', 'multiple_choice', 2, 'Why can we minimize $D^2$ instead of $D$?', '{"choices":["D² is always smaller","Squaring is increasing for nonnegative numbers, so both have the minimum at the same place","D isn''t differentiable","It changes the answer but is easier"],"answer":1}', '[]', 'And $D^2$ avoids a square root.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_15deaba6c5af8a', 'les_9ad1a5709ec4d6', 4, 'review', 'numeric', 3, 'An open box is made from a 16 × 10 sheet. What is its maximum volume?', '{"answer":144}', '[]', '$V''(x) = 12x^2 - 104x + 160 = 4(3x - 20)(x - 2)$; $x = 2$ is in $(0, 5)$; $V = 144$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7021f21faa35ce', 'subj_math', 'optimization', 'Optimization', 'Finding the largest or smallest value of a quantity using derivatives.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9ad1a5709ec4d6', (SELECT id FROM concepts WHERE slug = 'optimization'));

-- Lesson: u-substitution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ae133b18742e61', 'u-substitution', 'Integrating using substitution', 'Reverse the Chain Rule with u-substitution: choose u, rewrite dx in terms of du, integrate, and change limits for definite integrals.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ce10630ee9f31', 'les_ae133b18742e61', 1, 'Choose u as an inner function whose derivative appears in the integrand.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a055a43d75769b', 'les_ae133b18742e61', 2, 'Rewrite the integral completely in terms of u.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0743707244aed', 'les_ae133b18742e61', 3, 'Change the limits of integration for definite integrals.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ce10630ee9f31', 'les_ae133b18742e61', 'learn', 1, 'definition', '{"term":"Substitution","body":"If $u = g(x)$, then $du = g''(x)\\,dx$ and $\\int f(g(x))\\,g''(x)\\,dx = \\int f(u)\\,du$. For a definite integral, the limits become $g(a)$ and $g(b)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a055a43d75769b', 'les_ae133b18742e61', 'learn', 2, 'worked_example', '{"title":"$\\int 2x(x^2 + 1)^5\\,dx$","steps":[{"latex":"u = x^2 + 1,\\ du = 2x\\,dx","explanation":""},{"latex":"\\int u^5\\,du = \\frac{u^6}{6} + C = \\frac{(x^2 + 1)^6}{6} + C","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0743707244aed', 'les_ae133b18742e61', 'learn', 3, 'worked_example', '{"title":"$\\int_0^1 x e^{x^2}\\,dx$","steps":[{"latex":"u = x^2,\\ du = 2x\\,dx;\\ x: 0 \\to 1 \\Rightarrow u: 0 \\to 1","explanation":""},{"latex":"\\tfrac{1}{2}\\int_0^1 e^u\\,du = \\tfrac{1}{2}(e - 1) \\approx 0.859","explanation":"Adjust for the missing factor 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_379f820b054d03', 'les_ae133b18742e61', 'learn', 4, 'callout', '{"tone":"warning","title":"Don''t mix variables","body":"After substituting, the integral must contain only $u$ and $du$. If an $x$ is left over that you can''t express in $u$, try a different $u$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be5809b69223f2', 'les_ae133b18742e61', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Many physical rates have a \"function of a function\" form, like $te^{-t^2}$ in diffusion; substitution undoes the Chain Rule that produced them."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ce10630ee9f31', 'les_ae133b18742e61', 1, 'practice', 'numeric', 2, 'Evaluate $\int_0^{\pi/2} \cos x\,\sin^2 x\,dx$ to three decimal places.', '{"answer":0.333,"tolerance":0.001}', '["$u = \\sin x$."]', '$\int_0^1 u^2\,du = \frac{1}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a055a43d75769b', 'les_ae133b18742e61', 2, 'practice', 'numeric', 2, 'Evaluate $\int_0^1 \frac{1}{2x + 1}\,dx$ to three decimal places.', '{"answer":0.549,"tolerance":0.001}', '["$u = 2x + 1$."]', '$\frac{1}{2}\ln 3 \approx 0.549$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0743707244aed', 'les_ae133b18742e61', 3, 'practice', 'multiple_choice', 2, 'For $\int \frac{\ln x}{x}\,dx$, the best substitution is…', '{"choices":["$u = x$","$u = \\ln x$","$u = \\frac{1}{x}$","$u = x\\ln x$"],"answer":1}', '[]', '$du = \frac{1}{x}dx$; the answer is $\frac{(\ln x)^2}{2} + C$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_379f820b054d03', 'les_ae133b18742e61', 4, 'review', 'numeric', 3, 'Evaluate $\int_1^2 x\sqrt{x^2 - 1}\,dx$ to three decimal places.', '{"answer":1.732,"tolerance":0.001}', '["$u = x^2 - 1$, from 0 to 3."]', '$\frac{1}{2}\cdot\frac{2}{3}u^{3/2}\Big|_0^3 = \frac{1}{3}\cdot 3\sqrt{3} = \sqrt{3}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c82594985bd6b3', 'subj_math', 'antiderivatives', 'Antiderivatives', 'Functions whose derivative is a given function; written as indefinite integrals.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ae133b18742e61', (SELECT id FROM concepts WHERE slug = 'antiderivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ae133b18742e61', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 1);

-- Lesson: verifying-de-solutions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a57bb0b3bc32ef', 'verifying-de-solutions', 'Verifying solutions for differential equations', 'Check whether a function solves a differential equation by substituting it and its derivatives, and distinguish general from particular solutions.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b30004eeeaa49', 'les_a57bb0b3bc32ef', 1, 'Verify a solution by substitution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5eb00aea82e598', 'les_a57bb0b3bc32ef', 2, 'Recognize that a general solution contains arbitrary constants.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e56592a7d55a2b', 'les_a57bb0b3bc32ef', 3, 'Use an initial condition to pick a particular solution.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b30004eeeaa49', 'les_a57bb0b3bc32ef', 'learn', 1, 'definition', '{"term":"Verifying","body":"A function is a solution if substituting it (and its derivatives) makes the equation true for every $x$ in an interval."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5eb00aea82e598', 'les_a57bb0b3bc32ef', 'learn', 2, 'worked_example', '{"title":"Does $y = Ce^{3x}$ solve $y'' = 3y$?","steps":[{"latex":"y'' = 3Ce^{3x} = 3y","explanation":"Yes, for every constant C."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e56592a7d55a2b', 'les_a57bb0b3bc32ef', 'learn', 3, 'worked_example', '{"title":"Does $y = \\sin 2x$ solve $y'''' + 4y = 0$?","steps":[{"latex":"y'''' = -4\\sin 2x","explanation":""},{"latex":"-4\\sin 2x + 4\\sin 2x = 0","explanation":"Yes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c63154a8af28c5', 'les_a57bb0b3bc32ef', 'learn', 4, 'definition', '{"term":"General and particular","body":"$y = Ce^{3x}$ is the general solution (a family). The condition $y(0) = 5$ picks the particular solution $y = 5e^{3x}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0943b773d940bf', 'les_a57bb0b3bc32ef', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers check a proposed vibration model by substituting it into the equation of motion before trusting its predictions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b30004eeeaa49', 'les_a57bb0b3bc32ef', 1, 'practice', 'multiple_choice', 1, 'Is $y = x^2$ a solution of $xy'' = 2y$?', '{"choices":["Yes","No","Only at x = 0","Only for x > 0"],"answer":0}', '[]', '$x(2x) = 2x^2 = 2y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5eb00aea82e598', 'les_a57bb0b3bc32ef', 2, 'practice', 'multiple_choice', 2, 'Which solves $y'' = -2y$?', '{"choices":["$y = e^{2x}$","$y = 4e^{-2x}$","$y = -2x$","$y = x^{-2}$"],"answer":1}', '[]', '$y'' = -8e^{-2x} = -2y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e56592a7d55a2b', 'les_a57bb0b3bc32ef', 3, 'practice', 'multiple_choice', 2, '$y = Ce^{x^2}$ solves $y'' = 2xy$. Which particular solution has $y(0) = 3$?', '{"choices":["$y = e^{x^2} + 3$","$y = 3e^{x^2}$","$y = e^{3x^2}$","$y = 3x^2$"],"answer":1}', '[]', '$C = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c63154a8af28c5', 'les_a57bb0b3bc32ef', 4, 'review', 'multiple_choice', 3, 'Is $y = \cos x$ a solution of $y'''' + y = 0$? Of $y'''' - y = 0$?', '{"choices":["Both","Only y″ + y = 0","Only y″ − y = 0","Neither"],"answer":1}', '[]', '$y'''' = -\cos x$, so $y'''' + y = 0$ but $y'''' - y = -2\cos x$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2bf234e8f5f243', 'subj_math', 'differential-equations', 'Differential equations', 'Equations relating a function to its derivatives, used to model how quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a57bb0b3bc32ef', (SELECT id FROM concepts WHERE slug = 'differential-equations'));

